(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-nvfp4-video-dit"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-1\">一 · 从一次闪烁事故说起：BF16 推理的显存与带宽墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-2\">二 · 它解决什么：两级微缩放把 E2M1 的动态范围管住</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-3\">三 · 它不解决什么：注意力精度、VAE 像素域与 Amdahl 上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-4\">四 · 失败模式的可观测信号与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-5\">五 · 适用边界的判定清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-6\">六 · 失效边界：FP4 省下的是带宽，赔进去的是时空一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-7\">七 · 从潜变量到第一个 GEMM：patchify 与入口精度锚点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-8\">八 · 权重预打包：离线两级缩放的布局与读取代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-9\">九 · 激活按 token 块动态量化：amax 统计与离群值风险</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-10\">十 · FP4 MMA 与累加：SM100 上的主循环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-11\">十一 · 注意力与残差的精度保留：Amdahl 边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-12\">十二 · 出口反量化与 VAE 前的 bias 校正</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-13\">十三 · 失效边界：从 token 块到像素域的误差传导链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-14\">十四 · 两级缩放的逐项拆解与误差上界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-15\">十五 · 激活侧 per-token 块量化的 amax 统计与跨帧漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-16\">十六 · 融合反量化的 GEMM 数据流与累加器精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-17\">十七 · 精度分配的推导：为什么注意力不能进 FP4</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-18\">十八 · 残差补偿与 bias 校正的可实现形式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-19\">十九 · 从公式到 kernel 参数：块大小、tile 与 occupancy 的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-20\">二十 · 请求形态：什么样的负载吃到 NVFP4 的红利</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-21\">二十一 · 批大小：被激活显存与 kernel 效率双向夹住</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-22\">二十二 · 并发与连续批处理：聚合是配方的另一半</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-23\">二十三 · 负载不对时的三种病态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-24\">二十四 · 配方与 SLO 的对接</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-25\">二十五 · 负载配方：批量去噪才回本，小 GEMM 与剧烈运动是两道坎</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-26\">二十六 · 硬件档位：FP4 原生档与“可跑但不划算”档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-27\">二十七 · 并行拓扑：单卡 GEMM 流水优先，跨卡只切序列与 batch</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-28\">二十八 · 量化方案：静态权重 + 动态激活 + 精度保留清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-29\">二十九 · KV 与中间激活策略：BF16/FP8 保精度，按需回写 HBM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-30\">三十 · 调度参数：以每步去噪时延为 SLO 的批调度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-31\">三十一 · 可复现配置思路：从档位到参数的判定链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-32\">三十二 · 显存账本：权重、激活与潜变量的三段占用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-33\">三十三 · 带宽与反量化的Amdahl边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-34\">三十四 · 通信：单卡GEMM流水之外的规模瓶颈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-35\">三十五 · 功耗与热：FP4吞吐背后的能量账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-36\">三十六 · 尾延迟：谁在长视频上先崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-37\">三十七 · 规模放大后的瓶颈次序：反量化开销、注意力精度保留与批上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-38\">三十八 · 精度失败的三种签名：闪烁、条带、结构崩坏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-39\">三十九 · OOM的三条路径与显存账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-40\">四十 · 批抖动与路由不均：两个被混淆的现象</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-41\">四十一 · 尾延迟尖刺：从SLO反推监控点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-42\">四十二 · 回滚的分级与触发条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-43\">四十三 · 诊断顺序与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-44\">四十四 · 对照维度：省显存、省算力还是省带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-45\">四十五 · 决策表：按瓶颈与SLO选主算法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-46\">四十六 · 适用条件的量化判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-47\">四十七 · 组合顺序与误差预算分配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-48\">四十八 · 部署拓扑与算法选择的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-49\">四十九 · 选型的工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-video-dit-sec-50\">五十 · 与稀疏时空注意力及 FP8 路线的取舍边界</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:528px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 528.3 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">采样器产出潜变量z_t与时间步嵌入，进入DiT块</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">线性层权重预打包为NVFP4块（16元素共享FP8缩放，块间FP32全局缩…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">激活按token块动态量化为NVFP4，与权重在SM100 FP4 MMA…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">累加器保持FP32，输出经缩放因子还原后进入LayerNorm与时空注意力</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"446.3\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">KV/中间激活按需回写HBM，仅保留FP8残差用于误差补偿</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-nvfp4-video-dit-sec-1\">一 · 从一次闪烁事故说起：BF16 推理的显存与带宽墙</h3>\n<p>某条 720p、多镜头、时长数十秒的生成请求在 Blackwell 单卡上跑批量去噪。采样器每步产出潜变量 <em>z<sub>t</sub></em> 与时间步嵌入，进入 DiT 块；块内 QKV 与 FFN 的权重以 BF16 驻留 HBM，激活同样 BF16。请求并发上来后，激活显存把 batch 顶到上限，调度器只能缩小批；而每步 GEMM 的权重读取量按 BF16 字节数线性增长，HBM3e 带宽成为每步时延的下界。工程上表现为两个耦合症状：单步时延随分辨率上升而非线性恶化，端到端帧输出被拖长；更糟的是，为了压显存而临时插入的“边算边反量化”路径把逐层反量化的 SM 指令开销摊到每个 GEMM 前，低占用时访存延迟直接主导，加速比被 Amdahl 定律削平。这类事故的根因不是某个 kernel 写错，而是**权重与激活仍以 BF16/FP8 为主，Blackwell 的 FP4 张量核心吞吐与 HBM3e 带宽没有被用满**。NVFP4 视频 DiT 量化推理要解决的正是这个具体问题：把线性层权重与激活压到 4bit，让权重带宽降到 BF16 的约 1/4，同时把矩阵乘搬上原生 FP4 张量核心。</p>\n<p>但事故还有第二层。团队曾尝试直接把注意力里的 QK<sup>T</sup> 与 PV 也压到 FP4，结果注意力图在稀疏与稠密区域同时结构崩坏——FP4 对注意力 logits 误差极敏感。这说明该算法的适用边界从一开始就不是“全模型 4bit”，而是**精度分配**：仅 FFN 与投影走 FP4，注意力保留 FP8/BF16，残差与 LayerNorm 保持 BF16，VAE 解码前对最后一层输出做 BF16 反量化与 bias 校正。把这条边界写进部署配方，比调一个 kernel 更能决定线上是否闪烁。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-2\">二 · 它解决什么：两级微缩放把 E2M1 的动态范围管住</h3>\n<p>NVFP4 的数据格式是 E2M1 加两级缩放。离线阶段对每个 Linear 权重按 16 元素分组求 E4M3 微缩放因子，再求全局 FP32 二级缩放，打包为 NVFP4 块布局：</p>\n<div class=\"formula\">$$w\\approx s_{\\text{FP32}}\\cdot s_{\\text{E4M3}}^{(g)}\\cdot q_{\\text{E2M1}}$$</div>\n<p>其中 <em>s</em><sub>FP32</sub> 为 per-tensor 二级缩放，<em>s</em><sub>E4M3</sub><sup>(g)</sup> 为每组 16 元素的微缩放，<em>q</em><sub>E2M1</sub> 为 4bit 量化值。两级缩放的意义在于把块内动态范围收进 E2M1 可表达的区间，使相对误差满足</p>\n<div class=\"formula\">$$\\Delta_{\\text{rel}}\\approx\\frac{\\lVert W-\\hat{W}\\rVert_2}{\\lVert W\\rVert_2}\\le \\frac{\\sqrt{16}\\,2^{-3}}{2\\sqrt{3}}\\cdot\\frac{1}{s_{\\text{blk}}}$$</div>\n<p>也就是说，块内缩放越细，误差上界越紧。这正是它相对“整张量一个 scale”的实质改进：视频 DiT 的 FFN 权重分布跨层差异大，单尺度会让某些块的 4bit 网格过粗，误差一路累积到 VAE 解码端变成闪烁与条带。在线侧按数据流顺序：latent patch 经 patchify 进入 DiT block，LayerNorm 与残差保持 BF16；进入 QKV/FFN 前按 token 块统计 amax 并量化为 NVFP4；GEMM 调用 cuBLASLt/CUTLASS 的 Blackwell FP4 kernel，权重与激活均为 NVFP4，累加器 FP32，输出反量化回 BF16 写回。KV 与中间激活按需回写 HBM，仅保留 FP8 残差用于误差补偿。系统代价上，权重显存降至 BF16 的约 1/4，B200 HBM3e 带宽下 DiT 每步权重读取时间近似线性下降，长视频高分辨率 latent 的 batch 上限随之提升；FP4 张量核心峰值吞吐约为 FP8 的 2 倍。具体例子：一个以 FFN 为主干、权重读取主导每步时延的 DiT 块，在权重压到 NVFP4 后每步的权重搬运量按 1/4 缩减，batch 得以抬高，GEMM 吞吐向 FP4 峰值靠拢——但这一切只在 FFN 与投影上成立。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-3\">三 · 它不解决什么：注意力精度、VAE 像素域与 Amdahl 上限</h3>\n<p>边界的第一条是注意力。QK<sup>T</sup> 与 PV 必须在 FP8 或 BF16 下执行，FP4 对 logits 误差敏感，压下去就是注意力图失真、结构崩坏。第二条是像素域：4bit 误差若直接进入 VAE 解码会表现为闪烁，因此 VAE 解码前要对最后一层输出做 BF16 反量化与 bias 校正。第三条是加速比上限：残差、LayerNorm、注意力保留 FP8/BF16，整体加速比受 Amdahl 限制，端到端不会等于 FFN 局部的 2 倍。第四条是低 batch 与小 GEMM：两级缩放的反量化指令与 scale 加载开销可能超过 FP4 吞吐收益，端到端时延不降反升。这四条合起来定义了适用边界——**Blackwell 档位、计算受限的 FFN 与投影 GEMM、批大小足够让 FP4 kernel 进入高效区**。它不解决注意力算力节省，那是按内容动态分配精度与稀疏度的路线要处理的事，两者可叠加但误差来源不同；它也不解决长视频潜变量序列的调度与缓存复用问题，那些属于批调度与缓存层。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>本算法覆盖</th><th>明确不覆盖</th></tr></thead><tbody><tr><td>权重与激活位宽</td><td>FFN/投影 NVFP4，两级微缩放</td><td>注意力 QK<sup>T</sup>/PV 的 4bit</td></tr><tr><td>显存与带宽</td><td>权重降至 BF16 约 1/4</td><td>KV cache 的 2bit 压缩</td></tr><tr><td>吞吐</td><td>FP4 MMA 约 FP8 的 2 倍（局部）</td><td>端到端等比例加速</td></tr><tr><td>稳定性</td><td>per-token amax、VAE 前 bias 校正</td><td>运动剧烈片段的全部误差</td></tr></tbody></table>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-4\">四 · 失败模式的可观测信号与工程判断</h3>\n<p>第一类失败模式是运动剧烈片段的 per-token 块量化误差上升，误差累积到 VAE 解码端表现为闪烁与条带。可观测信号不在 GEMM 侧，而在解码侧：同一潜变量序列在相邻帧间的像素差分出现高频抖动，且抖动集中在运动区域。工程判断是——per-token 块量化必须按 token 统计 amax 以适应跨帧动态范围，对运动剧烈片段保留注意力与残差为 FP8/BF16，而不是一味追求全 4bit。第二类失败模式是低 batch 或小 GEMM 下反量化与 scale 加载开销吃掉收益，表现为端到端时延不降反升；判断依据是每步时延里反量化指令占比与 scale 读取的访存延迟，处置是保持足够批大小让 FP4 kernel 进入高效区，必要时对小 GEMM 回退 FP8。第三类是把注意力也压到 FP4 导致注意力图失真，这属于精度分配错误而非量化算法错误，修的是配方不是 kernel。这三类失败模式共同指向一个工程结论：NVFP4 视频 DiT 的收益是**条件收益**，条件由批大小、精度分配与运动强度共同给出；把条件写成部署配方里的显式约束，比事后调参更能稳住 SLO。</p>\n<p>从容量规划角度看，该算法把权重显存与每步权重读取时间压下来，换来的是长视频高分辨率 latent 的 batch 上限提升；但 SLO 以每步去噪时延与端到端帧输出为主，因此容量模型必须把注意力与残差的 FP8/BF16 路径计入，不能按 FFN 局部的 2 倍吞吐外推整机吞吐。请求形态是高分辨率长视频 latent 的批量去噪，批大小同时受激活显存与 FP4 kernel 效率约束——这两个约束方向相反，前者要小批省显存，后者要大批摊薄反量化开销，配方就是在两者之间取一个使每步时延稳定的批区间。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-5\">五 · 适用边界的判定清单</h3>\n<p>落到可执行的判定：其一，硬件必须是 Blackwell 档位，依赖原生 FP4 张量核心与 HBM3e 带宽，非 Blackwell 上该算法退化为纯软件反量化，收益不成立。其二，负载必须是计算受限的 FFN 与投影 GEMM 占主导的 DiT 结构；若某模型注意力占比高，Amdahl 上限会先把收益吃掉。其三，批大小要足够，使两级缩放的反量化指令与 scale 加载被 GEMM 主循环摊薄；低 batch 场景应显式回退。其四，精度分配必须固定为权重与激活 NVFP4、注意力 FP8/BF16、残差与 LayerNorm BF16、KV 保持 BF16 或 FP8 的混合精度配方，任何“顺手把注意力也压了”的改动都要单独验证。其五，校准集要覆盖跨帧动态范围，per-token 块量化的 amax 统计偏差会放大时空注意力误差，这是校准集偏差而非 kernel 缺陷。并行拓扑以单卡内 GEMM 流水为主，量化方案与并行方式解耦，跨卡扩展不属于本算法的讨论范围。</p>\n<p>把这些条件合起来看，NVFP4 视频 DiT 量化推理的定位很清楚：它是一层**静态的权重与激活 4bit 量化**，用来省显存、提 GEMM 吞吐，作用域被精度分配切得很窄。窄作用域不是缺陷，而是它能在视频这种时空激活动态范围极大的负载上不闪烁的前提——把 4bit 关在 FFN 与投影里，把注意力与像素域留给 FP8/BF16，两级缩放与残差补偿才有意义。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-6\">六 · 失效边界：FP4 省下的是带宽，赔进去的是时空一致性</h3>\n<p>一个可复现的线上失败案例足以界定这条路径的边界。某条高分辨率长视频生成服务在 B200 上把 DiT 全部线性层（含 QKV、注意力投影、FFN）统一压到 NVFP4，离线打包与在线 per-token 块量化都按标准流程执行，离线校准集取自慢速运镜的风景片段。上线后静态镜头一切正常，但一旦出现快速横摇、人群穿行或镜头内多物体交错遮挡，输出开始出现跨帧不一致的亮度跳变与块状条带，越到 VAE 解码端越明显——因为 4bit 量化误差在潜变量空间里只是小幅偏移，经过 VAE 的上采样与像素域重建后被放大成可见闪烁。根因不在量化算子本身，而在两处被忽视的分配：注意力 logits 对 FP4 的 E2M1 网格极敏感，QK^T 与 PV 一旦走 FP4，softmax 前的分数误差直接扭曲注意力图，稀疏区与稠密区同时结构崩坏；而 per-token 块量化的 amax 是按 token 统计的，运动剧烈片段的跨帧动态范围远超校准集覆盖，缩放因子系统性偏小，误差随去噪步数累积。</p>\n<p>这条路径的适用边界可以用一条相对误差界说明。块内 16 元素共享一个 E4M3 微缩放、块间再套一个 FP32 全局缩放，两级缩放写作 $w\\approx s_{FP32}\\cdot s_{E4M3}^{(g)}\\cdot q_{E2M1}$，其重建误差上界为</p>\n<div class=\"formula\">$$\\Delta_{\\text{rel}}\\approx\\frac{\\lVert W-\\hat{W}\\rVert_2}{\\lVert W\\rVert_2}\\le \\frac{\\sqrt{16}\\,2^{-3}}{2\\sqrt{3}}\\cdot\\frac{1}{s_{\\text{blk}}}$$</div>\n<p>关键在分母上的 $s_{\\text{blk}}$：块内动态范围越大，微缩放被迫取大，相对误差随之抬升。视频激活恰恰是动态范围最大的那一类——同一 token 块在不同帧上的幅值可以差出数量级，因此 NVFP4 的精度红利只在“块内幅值分布集中”的张量上成立。这就解释了为什么该方案必须做静态精度分配：FFN 与投影的权重分布相对平稳，可以整层走 FP4；注意力 QK^T 与 PV 必须保留 FP8 或 BF16；LayerNorm 与残差保持 BF16；KV 保持 BF16 或 FP8。任何试图把注意力也压到 4bit 的“统一量化”都会越过这条界。</p>\n<p>第二类失效来自系统代价而非数值。两级缩放意味着每个 16 元素块都要读一次 E4M3 因子、每个张量读一次 FP32 全局缩放，反量化与缩放因子加载会插入额外 SM 指令。当批大小足够、GEMM 形状足够大时，这些开销被 FP4 张量核心的吞吐（约为 FP8 的 2 倍）与权重带宽降至 BF16 约 1/4 的收益淹没；但在低 batch 或小 GEMM 场景下，流水被访存延迟主导，反量化指令占比上升，端到端每步去噪时延不降反升，加速比被 Amdahl 定律卡在注意力与残差这些非 FP4 段落上。因此负载配方上必须维持足够批大小，让 FP4 kernel 处于计算受限区；批大小本身又受激活显存约束，形成一个需要容量规划来解的耦合。下表给出该方案“解决/不解决”的清晰切分。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>解决</th><th>不解决（失效条件）</th></tr></thead><tbody><tr><td>显存与带宽</td><td>FFN/投影权重降至 BF16 约 1/4，长视频 latent 的 batch 上限提升</td><td>注意力 KV 与残差仍需 BF16/FP8，显存下限由它们决定</td></tr><tr><td>算力吞吐</td><td>计算受限的大 GEMM 走原生 FP4 MMA，峰值约为 FP8 的 2 倍</td><td>低 batch/小 GEMM 下反量化与 scale 加载抵消收益</td></tr><tr><td>数值精度</td><td>块内动态范围可控，配合 FP8 残差补偿把端到端 FVD 退化压在可接受范围</td><td>运动剧烈片段 per-token 误差上升，VAE 端表现为闪烁与条带</td></tr><tr><td>精度分配</td><td>静态分层：FFN/投影 FP4、注意力 FP8/BF16、LayerNorm/残差 BF16</td><td>注意力压到 FP4 导致 logits 失真、注意力图结构崩坏</td></tr></tbody></table>\n<p>还有一条容易被误判的边界：这套方案与按内容动态分配精度与稀疏度的稀疏时空注意力并不互为替代。后者省的是注意力算力与带宽，误差来源是稀疏化近似；前者省的是权重与激活的显存占用并提升 GEMM 吞吐，误差来源是 4bit 网格与缩放因子。两者可以叠加，但叠加后误差不再可加性地归因，校准集偏差会同时放大两条路径的误差。工程判断因此落在三件事上：把 FP4 严格限制在计算受限的 FFN 与投影 GEMM；在 VAE 解码前对最后一层输出做 BF16 反量化与 bias 校正，阻断 4bit 误差进入像素域；以及按 token 统计 amax 并针对运动剧烈片段保留注意力与残差的 FP8/BF16 通路——这三条不是调优选项，而是该算法成立的前提条件。</p>\n<h3 id=\"alg-nvfp4-video-dit-sec-7\">七 · 从潜变量到第一个 GEMM：patchify 与入口精度锚点</h3>\n<p>采样器每步吐出潜变量 <em>z_t</em> 与时间步嵌入，二者先经 patchify 折叠成 token 序列。这一步的输入是 BF16 的 latent 张量（形状按批、帧、通道、高、宽组织），输出是展平后的 token 矩阵，代价主要落在 HBM 读写：长视频高分辨率 latent 的体量随帧数与空间分辨率线性增长，patchify 本身不做算术，却决定了后续所有 GEMM 的 M 维大小，也就决定了 FP4 kernel 能否进入高效区间。工程上要盯的是 token 数而非像素数——token 数太少，两级缩放的反量化指令与 scale 加载开销会盖过 FP4 吞吐收益。</p>\n<p>入口处必须钉死精度锚点：LayerNorm 与残差通路保持 BF16，不参与量化。原因是残差是跨层累加的，任何 4bit 舍入都会在深度方向上叠加；LayerNorm 的均值方差统计对量化噪声敏感，压到 FP4 会让归一化后的分布偏移。具体做法是 patchify 输出先写回 HBM 的 BF16 缓冲，再由下游量化内核读取，这一步多一次往返，但换来了残差通路的数值稳定。时间步嵌入经 MLP 调制后以 BF16 注入各块的 scale-shift 参数，同样不量化。</p>\n<p>以一个批量去噪请求为例：批内每条样本的 latent 在 patchify 后拼成同一 token 矩阵送入 DiT block 栈，入口的 BF16 缓冲占用与 token 数成正比，这是批大小的第一个硬约束。若把入口缓冲也压到 FP8，能省一半显存，但残差回写路径就要引入额外的反量化，得不偿失。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-8\">八 · 权重预打包：离线两级缩放的布局与读取代价</h3>\n<p>权重侧在服务启动前完成离线打包，按 16 元素一组求 E4M3 微缩放因子，再对整个张量求 FP32 二级缩放，量化值为 E2M1。写成式子即</p>\n<div class=\"formula\">$$w\\approx s_{FP32}\\cdot s_{E4M3}^{(g)}\\cdot q_{E2M1},\\quad \\hat{W}_{i}=s_{\\text{blk},i}\\cdot s_{\\text{glob}}\\cdot \\mathrm{deq}(W^{\\text{FP4}}_{i})$$</div>\n<p>打包后的块布局要让一个 warp 在一次事务里取到整组 16 个 4bit 值加一个 8bit 缩放，避免缩放因子分散在独立页造成额外事务。相对误差上界由两级缩放共同约束：</p>\n<div class=\"formula\">$$\\Delta_{\\text{rel}}\\approx\\frac{\\lVert W-\\hat{W}\\rVert_2}{\\lVert W\\rVert_2}\\le \\frac{\\sqrt{16}\\,2^{-3}}{2\\sqrt{3}}\\cdot\\frac{1}{s_{\\text{blk}}}$$</div>\n<p>可见块内动态范围越小、微缩放越贴合，误差越小；这也是分组粒度选 16 而非 32 的原因——视频 DiT 的 FFN 权重列间差异大，组太大微缩放会被离群元素拖偏。</p>\n<p>读取代价是这条路径的核心账：权重显存降至 BF16 的约 1/4，在 B200 的 HBM3e 带宽下，DiT 每步的权重读取时间近似线性下降，长视频高分辨率 latent 的 batch 上限随之提升。但缩放因子本身要占带宽——每 16 个 4bit 值配 1 字节 E4M3 加一个 per-tensor FP32，摊到每元素约 0.0625 字节缩放开销，相对 0.5 字节的权重主体不可忽略。工程判断是：把 per-tensor 二级缩放提到 kernel 参数里常量传入，避免每块重复加载。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-9\">九 · 激活按 token 块动态量化：amax 统计与离群值风险</h3>\n<p>进入 QKV 与 FFN 之前，激活按 token 块统计 amax 并量化为 NVFP4。输入是 BF16 的归一化激活，输出是 NVFP4 激活块加对应的 E4M3 微缩放与 FP32 全局缩放。按 token 而非按通道分组，是因为视频时空激活的跨帧动态范围体现在 token 维度：同一通道在不同帧的幅值差异远大于同一帧内不同通道的差异。</p>\n<p>伪代码思路是：对每个 token 块先求 <code>amax = max(|x|)</code>，令 <code>s_E4M3 = amax / 6</code>（E2M1 可表示的最大幅值为 6），再令 <code>s_FP32 = 1</code> 或按块间归一化取值，最后 <code>q = round(x / (s_FP32·s_E4M3))</code> 截断到 E2M1 网格。这一步的代价是每 token 块一次归约加一次除法，属于访存受限的小内核；在低占用、小 batch 时它会被 HBM 延迟主导，成为 Amdahl 意义上的串行段。</p>\n<p>风险集中在离群值：E2M1 只有 4 个指数位宽的有效动态范围，单个 token 内的尖峰会把同组其余元素压到零附近。运动剧烈片段的激活幅值跳变最明显，per-token 量化误差在此上升，误差沿层累积到 VAE 解码端就表现为闪烁与条带。缓解手段是校准集必须覆盖高运动场景，且对运动剧烈片段保留注意力与残差为 FP8/BF16；校准集偏差会直接放大时空注意力误差，这是该算法最脆弱的环节。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-10\">十 · FP4 MMA 与累加：SM100 上的主循环</h3>\n<p>权重与激活均为 NVFP4 后，GEMM 调用 cuBLASLt 或 CUTLASS 的 Blackwell FP4 kernel，在 SM100 的 FP4 张量核心上直接相乘，累加器保持 FP32。这是整条链路唯一真正吃到 FP4 吞吐的环节：Blackwell FP4 张量核心峰值吞吐约为 FP8 的 2 倍，而权重带宽已降到 BF16 的 1/4，两个方向的收益在此叠加。</p>\n<p>主循环的输入是 NVFP4 权重块、NVFP4 激活块与两级缩放因子，输出是 FP32 累加结果，经缩放因子还原后反量化回 BF16 写回 HBM，再进入 LayerNorm 与时空注意力。融合反量化的关键是把缩放乘法放在累加之后而非逐元素乘：<code>acc = Σ q_w·q_x</code>，再整体乘 <code>s_w·s_x</code>，这样每输出元素只做一次缩放，而不是每乘加一次。代价是缩放因子必须在 kernel 内可见，且两级缩放的乘积要在寄存器里预先合成。</p>\n<p>并行拓扑以单卡内 GEMM 流水为主，不跨卡切分单个 GEMM。原因是 FP4 kernel 的效率依赖足够大的 M 维，切分会让每卡 GEMM 变小、反量化开销占比上升。批大小受激活显存与 FP4 kernel 效率双重约束：批太小则 M 维不足，两级缩放的指令开销抵消收益，端到端时延不降反升；批太大则激活显存溢出。这个窗口需要在容量规划时实测标定，而非按峰值吞吐推算。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-11\">十一 · 注意力与残差的精度保留：Amdahl 边界</h3>\n<p>注意力中 QK^T 与 PV 在 FP8 或 BF16 下执行，不进入 FP4。原因是 FP4 对注意力 logits 误差极敏感：logits 经 softmax 后是指数放大，4bit 舍入会让注意力图在稀疏与稠密区域同时失真，结构崩坏。仅 FFN 与投影走 FP4，这是精度分配的核心约束。</p>\n<p>代价直接体现在加速比上：注意力与残差保留 FP8/BF16，意味着每步去噪的算力与带宽有一部分不吃 FP4 收益，整体加速比受 Amdahl 限制。设 FFN 与投影占每步 FLOPs 的比例为 <em>p</em>，FP4 相对 FP8 的吞吐倍率为 2，则理论上界约为</p>\n<div class=\"formula\">$$S\\le \\frac{1}{(1-p)+p/2}$$</div>\n<p>若 <em>p</em> 不够大，端到端收益会被注意力段稀释。工程判断是：先测出目标模型在目标分辨率下的 <em>p</em>，再决定是否值得为 FFN 单独做 FP4 路径；若 <em>p</em> 偏低，把注意力也压到 FP8 以下的收益风险比不划算。KV 保持 BF16 或 FP8 以维持注意力精度，KV 的量化是另一条独立路径，不在本算法的范围内。</p>\n<p>中间激活按需回写 HBM，仅保留 FP8 残差用于误差补偿。残差补偿的作用是把 4bit 量化在 FFN 输出上引入的偏差，用一份低精度残差在下一层入口处补回，代价是额外一份 FP8 缓冲的显存与一次读写。这份缓冲的体量与 token 数成正比，是激活显存的第二个约束项。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-12\">十二 · 出口反量化与 VAE 前的 bias 校正</h3>\n<p>最后一层 DiT block 的输出不能直接以 FP4 状态进入 VAE。出口处做 BF16 反量化并施加 bias 校正，把 4bit 量化在通道均值上引入的系统性偏移拉回。输入是 FP32 累加经缩放还原后的张量，输出是 BF16 的 latent，代价是一次全量反量化写回加一次逐通道加法，相对整步去噪可忽略，但缺了它，4bit 误差会直接进入像素域造成闪烁。</p>\n<p>bias 校正在离线阶段用校准集统计每通道的输出均值偏差，在线只做加法。校准集偏差在此再次放大：若校准集缺少高运动片段，校正量本身就有偏，出口处的补偿反而引入新的系统性误差。因此校准集的覆盖度是这条链路从入口到出口的共同前提，而不是某一环节的局部问题。</p>\n<p>整条链路的顺序代价可以这样记：patchify 定 M 维，权重预打包定带宽，per-token 量化定精度风险，FP4 MMA 定吞吐收益，注意力精度保留定 Amdahl 上界，出口校正定像素域质量。六个环节里任何一环的窗口失配——批太小、校准集偏差、<em>p</em> 偏低——都会让端到端加速比落在预期之外。工程上应把批大小与 <em>p</em> 作为部署前的两个必测标定量，而不是事后调参。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-13\">十三 · 失效边界：从 token 块到像素域的误差传导链</h3>\n<p>本方案的静态量化收益并不均匀分布在整条数据流上，真正决定成败的是三个断点：激活 amax 统计的窗口、注意力精度的保留位宽、以及 VAE 前的最后一次反量化。按 token 块统计 amax 时，窗口只覆盖当前 patch 化后的 token 子集，跨帧运动剧烈片段里同一空间位置在不同时间步的激活幅值差异会被压进同一个 E4M3 微缩放因子，块内 E2M1 只有 16 个可表示电平，一旦 amax 被少数离群通道抬高，其余通道的有效位数就被挤掉。误差上界可写成</p>\n<div class=\"formula\">$$\\Delta_{\\text{rel}}\\approx\\frac{\\lVert W-\\hat{W}\\rVert_2}{\\lVert W\\rVert_2}\\le \\frac{\\sqrt{16}\\,2^{-3}}{2\\sqrt{3}}\\cdot\\frac{1}{s_{\\text{blk}}}$$</div>\n<p>该式说明块内相对误差与微缩放因子成反比：$s_{\\text{blk}}$ 越小（即该 16 元素组幅值越集中在小值区），量化台阶占比越大。视频潜变量的高频纹理块恰好落在这一区间，误差经 FFN 与投影逐层累加，最终在 VAE 解码端表现为帧间闪烁与条带——这是定性可预期的失效模式，而非偶发噪声。校准集若偏向静态场景，per-token 块 amax 会系统性低估运动片段的动态范围，误差放大在时空注意力之前的 QKV 投影上最明显。</p>\n<p>第二个断点是精度分配。QK^T 与 PV 保留 FP8/BF16 不是保守选择，而是硬约束：FP4 的 E2M1 对注意力 logits 的指数级敏感，softmax 前的微小绝对误差会改变归一化后的注意力图，稀疏区与稠密区同时出现结构崩坏。因此整条流水线的加速比被 Amdahl 定律钳制在 FFN 与投影 GEMM 的占比上，可写成</p>\n<div class=\"formula\">$$S_{\\text{e2e}}\\le \\frac{1}{(1-f_{\\text{FFN}})+f_{\\text{FFN}}/2}$$</div>\n<p>其中 $f_{\\text{FFN}}$ 为可 FP4 化的 GEMM 时间占比，2 为 FP4 相对 FP8 的吞吐倍数。注意力与残差保持高精度意味着 $1-f_{\\text{FFN}}$ 这一项无法压缩，端到端收益天花板由此确定；把注意力也压到 FP4 换来的吞吐增量会被结构崩坏抵消，属于不可接受的交换。</p>\n<p>第三个断点是系统代价的形状。权重显存降至 BF16 的约 1/4，B200 HBM3e 带宽下每步权重读取时间近似线性下降，长视频高分辨率 latent 的 batch 上限随之提升——但这条收益曲线在低 batch 或小 GEMM 时反转：两级缩放要求每个 16 元素块读取一个 E4M3 微缩放因子加一个 per-tensor FP32 全局缩放，反量化指令与 scale 加载在 SM 上引入额外开销，当 GEMM 规模不足以让 FP4 张量核心进入稳态流水，访存延迟而非算力成为主导，端到端时延不降反升。工程判断因此落在批大小下限上：必须让 FP4 kernel 的 MMA 流水覆盖反量化开销，否则应退回 FP8 路径。下表给出三个断点的输入、输出与代价对照。</p>\n<table class=\"mini\"><thead><tr><th>断点</th><th>输入</th><th>输出</th><th>系统代价</th></tr></thead><tbody><tr><td>per-token 块量化</td><td>BF16 激活、token 块 amax</td><td>NVFP4 激活 + E4M3/FP32 缩放</td><td>额外 SM 指令与 scale 读取，低占用时被访存延迟主导</td></tr><tr><td>注意力精度保留</td><td>FP8/BF16 QKV</td><td>FP8/BF16 logits 与 PV</td><td>Amdahl 上限，注意力时间不随 FP4 吞吐缩放</td></tr><tr><td>VAE 前反量化</td><td>FP4 末层输出 + bias</td><td>BF16 像素域输入</td><td>一次全量反量化与校正，误差不再进入像素域</td></tr></tbody></table>\n<p>适用边界由此清晰：Blackwell 档位、计算受限的 FFN 与投影 GEMM、足够批大小使 FP4 流水饱和；规模上限由注意力精度保留与反量化开销共同封顶。运动剧烈片段应保留注意力与残差为 FP8/BF16 并对 per-token amax 做跨帧平滑，VAE 前的 bias 校正则是阻断 4bit 误差进入像素域的最后一道闸门——它不提升吞吐，但决定了这套量化能否在长视频上稳定交付。</p>\n<h3 id=\"alg-nvfp4-video-dit-sec-14\">十四 · 两级缩放的逐项拆解与误差上界</h3>\n<p>把权重写成 <span class=\"formula-inline\">w ≈ s<sub>FP32</sub> · s<sub>E4M3</sub><sup>(g)</sup> · q<sub>E2M1</sub></span>，三项各有明确分工，不能混为一谈。q<sub>E2M1</sub> 是 E2M1 的 4 位编码：1 位符号、2 位指数、1 位尾数，可表示值域为 {0, ±0.5, ±1, ±1.5, ±2, ±3, ±4, ±6}，相邻可表示值之间的相对间距在最坏处达到 2<sup>-1</sup> 量级，这就是为什么必须靠缩放把数据搬进这个稀疏栅格的内侧。s<sub>E4M3</sub><sup>(g)</sup> 是每 16 个元素一组的微缩放，用 FP8 E4M3 存储，因此它自身只有 3 位尾数——这意味着微缩放因子本身带量化误差，它不是一个精确的实数，而是被再次栅格化的近似值。s<sub>FP32</sub> 是 per-tensor 的二级缩放，FP32 存储，作用是把整块权重的动态范围归一到微缩放可表达的区间内，避免 E4M3 在极小或极大值上溢出或下溢。</p>\n<p>推导的关键一步在于把两级缩放合并成单一有效缩放，再对块内误差做最坏情况估计。设某组 16 元素的最大绝对值为 amax<sub>g</sub>，则理想微缩放 s<sub>g</sub> = amax<sub>g</sub> / 6（6 是 E2M1 的最大可表示幅值）。E2M1 在幅值 x 处的舍入误差上界为半个相邻间距，而在该栅格上相邻间距与幅值成正比，最坏相对误差出现在最小非零量级附近，其绝对误差不超过 s<sub>g</sub>·2<sup>-3</sup>（尾数 1 位，半个 ulp 即 2<sup>-1</sup>·2<sup>-2</sup>）。把 16 个元素的误差按欧氏范数累积，得到块级误差上界 √16·s<sub>g</sub>·2<sup>-3</sup>；再用权重范数 ‖W‖<sub>2</sub> 归一，并注意到均匀分布假设下每组范数与全局范数的比例关系给出 2√3 这个常数因子，就得到给定事实中的那条界：</p>\n<div class=\"formula\">$$\\Delta_{\\text{rel}}\\approx\\frac{\\lVert W-\\hat{W}\\rVert_2}{\\lVert W\\rVert_2}\\le \\frac{\\sqrt{16}\\,2^{-3}}{2\\sqrt{3}}\\cdot\\frac{1}{s_{\\text{blk}}}$$</div>\n<p>这条不等式真正要读的是最后那个 1/s<sub>blk</sub>：误差上界与块缩放因子成反比。s<sub>blk</sub> 越小（块内幅值越小、量化栅格越密），相对误差越大——这正是小幅值块的危险区。工程含义是分组不能只看「16 个元素共享一个缩放」这一形式，还要看这 16 个元素是否同量级；若一个块里混进了离群值，amax 被抬高，s<sub>g</sub> 变大，块内其余 15 个正常元素的相对误差随之恶化。这就是为什么权重侧要按 16 元素分组而不是更大粒度：组越小，离群值污染的范围越窄。</p>\n<p>代价面：这条界是范数意义下的上界，不是逐元素保证。视频 DiT 的 FFN 权重通常比投影层更「重尾」，若某层出现成片的小幅值权重，Δ<sub>rel</sub> 会逼近上界，端到端表现为该层输出整体偏移，经 LayerNorm 后被部分吸收，但进入时空注意力前的残差通路会把它带下去。判断一个层能否安全走 FP4，实操上是先离线算每层的 Δ<sub>rel</sub> 估计值与该层输出对最终 latent 的敏感度，而不是全局一刀切。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-15\">十五 · 激活侧 per-token 块量化的 amax 统计与跨帧漂移</h3>\n<p>权重是离线打包的，激活是每步在线量化的，两者的误差性质完全不同。激活量化按 token 块统计 amax：对一个 token 的全部通道（或一个 token 在一个 tile 内的通道切片）取最大绝对值，据此定出该 token 块的缩放，再把通道值映射到 E2M1 栅格。伪代码思路如下，注意它必须与 GEMM 的 tile 划分对齐，否则缩放因子无法在 kernel 内被高效复用：</p>\n<ul>\n<li>对输入激活 X（形状 [tokens, channels]）按 token 分块，块大小与 FP4 MMA 的 K 维 tile 对齐；</li>\n<li>逐块求 amax<sub>t</sub> = max(|X[t, :]|)，除以 6 得 s<sub>t</sub>，并检查 s<sub>t</sub> 是否落在 E4M3 可表示区间，否则回退到更粗的块或提升到 FP8；</li>\n<li>量化 q<sub>t</sub> = round<sub>E2M1</sub>(X[t, :] / s<sub>t</sub>)，同时把 s<sub>t</sub> 以 E4M3 写入 scale 缓冲；</li>\n<li>GEMM 时权重块缩放与激活 token 缩放相乘，作为该 tile 的输出还原系数，累加器保持 FP32；</li>\n<li>输出乘以合并缩放写回 BF16，进入 LayerNorm。</li>\n</ul>\n<p>关键机制在于 amax 是逐 token 的，而视频 latent 的 token 在时间维上并不独立：同一空间位置在不同帧的激活幅值会随运动剧烈程度变化。运动平缓的片段，跨帧 amax 稳定，per-token 缩放几乎不漂移；运动剧烈片段，同一 token 位置的幅值在相邻帧间可能相差数倍，导致每帧独立定的 s<sub>t</sub> 在帧间跳变，量化栅格随之伸缩，误差不再是一致性偏差而是帧间不一致的扰动——这正是闪烁的来源。给定事实里把这条列为失败模式，其机理就是缩放因子的时域非平稳性。</p>\n<p>代价面：per-token 统计需要一次额外的 reduction（求 amax），它在 GEMM 之前串行执行，对低占用小 batch 是纯开销；scale 缓冲的读写也占带宽。缓解手段是让 amax 统计与上一层输出融合，避免单独一趟读激活；但融合会拉长 kernel 的依赖链，在 batch 足够大、GEMM 占主导时这笔开销被摊薄，在 batch 小、GEMM 短时则成为主导项。这就是 Amdahl 限制在激活量化侧的具体落点：加速比的上限由未被 FP4 化的那部分（amax 统计、缩放还原、注意力）决定。</p>\n<p>具体例子：一个 720p 级别的长视频 latent 序列进入 DiT 的 FFN，token 数达数万量级，通道数千。若逐 token 独立量化，运动剧烈段的 token 其 s<sub>t</sub> 在相邻去噪步之间可能变化显著，导致同一空间位置在连续步上的量化误差方向不一致，累积到 VAE 解码端就是条带。工程上的处理不是放弃 per-token，而是对运动剧烈段保留 FP8/BF16 通路（见精度分配），让 FP4 只覆盖统计稳定的 token 块。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-16\">十六 · 融合反量化的 GEMM 数据流与累加器精度</h3>\n<p>FP4 MMA 的输入是打包的 4 位值，硬件在 tensor core 内部完成乘加，但缩放还原不在 MMA 指令里自动完成，必须由 kernel 显式做。数据流是：权重块以 NVFP4 布局预打包（每 16 元素附带一个 E4M3 微缩放，per-tensor 一个 FP32 全局缩放），激活按 token 块量化后同样打包；MMA 以 FP4×FP4 输入、FP32 累加器执行；每个 K 维 tile 完成后，把该 tile 的权重微缩放与激活 token 缩放相乘，得到一个 tile 级还原系数，累加到输出前统一应用。伪代码层面可写成：</p>\n<ul>\n<li>acc = 0（FP32）；对 K 维按 tile 循环：acc += mma_fp4(W_tile, X_tile)；</li>\n<li>每个 tile 记录 scale<sub>tile</sub> = s<sub>W,g</sub> · s<sub>X,t</sub>，若各 tile 缩放不同则需在累加前分别还原，或把缩放并入部分和缓冲；</li>\n<li>循环结束后 out = acc · s<sub>FP32</sub> · s<sub>tile,merged</sub>，转 BF16 写回；</li>\n<li>残差补偿项（仅保留 FP8 残差）在写回前叠加，抵消系统性偏差。</li>\n</ul>\n<p>这里有一个必须讲清的取舍：若各 K tile 的缩放不同，就不能简单地把所有 tile 的部分和直接相加再乘一个总缩放——那等于假设缩放沿 K 维恒定。正确做法是每个 tile 的部分和先乘自己的缩放再累加，代价是每 tile 一次 FP32 乘加，指令数随 K/tile 线性增长。若为省指令而把缩放统一成 per-tensor，就退化成单级缩放，块内动态范围失控，Δ<sub>rel</sub> 的上界不再受 1/s<sub>blk</sub> 保护。融合反量化的工程价值就在于把这个乘加藏进 MMA 流水线的间隙里，让缩放还原与下一次 MMA 发射重叠。</p>\n<p>累加器保持 FP32 不是可选项：FP4 输入的有效位极少，若累加也用低精度，K 维长归约的舍入误差会随 √K 增长，而 FP32 累加把这个增长压到可忽略。代价是累加器占寄存器/共享内存，tile 越大占用越高，直接限制 occupancy。这就是为什么 FP4 kernel 的 tile 形状与 BF16 kernel 不同：输入位宽降了，但累加器位宽没降，寄存器压力反而成为调优主变量。</p>\n<p>代价面：反量化与缩放因子读取引入额外 SM 指令，在低占用小 batch 时被访存延迟主导——scale 缓冲的一次读可能比一次 MMA 还慢。给定事实把这条列为失败模式之二，其判据是：当 GEMM 的 K 维不足以摊薄 scale 加载延迟时，FP4 吞吐优势被指令开销吃掉，端到端时延不降反升。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-17\">十七 · 精度分配的推导：为什么注意力不能进 FP4</h3>\n<p>给定事实明确：QK<sup>T</sup> 与 PV 在 FP8 或 BF16 下执行，仅 FFN 与投影走 FP4。这不是经验拍板，可以从误差传播推出来。注意力 logits 经过 softmax，softmax 对输入扰动的敏感度与 logits 的动态范围正相关：logits 幅值越大，exp 后的分布越尖锐，微小的 logits 误差就能把概率质量从一个位置搬到另一个位置。FP4 的 E2M1 栅格在幅值较大处相对间距达 2<sup>-1</sup>，落到 logits 上就是足以改变注意力图结构的扰动——稀疏区与稠密区同时出现结构崩坏，这正是失败模式之三。</p>\n<p>推导的关键一步是把误差从 logits 传到输出：设 logits 扰动为 δ，softmax 输出扰动上界约为 ‖δ‖<sub>∞</sub> 量级（在分布未饱和时），而 PV 的输出误差又正比于注意力权重的扰动乘以 V 的幅值。若 δ 由 FP4 量化引入且与 logits 幅值成正比，则注意力权重误差在 logits 大幅值处不收敛。相比之下 FFN 是逐 token 的逐元素非线性，误差不经过跨 token 的归一化放大，且 FFN 权重与激活的分布更接近量化友好的重尾形态，Δ<sub>rel</sub> 的上界更容易被满足。</p>\n<p>代价面：保留注意力为 FP8/BF16 意味着这部分 GEMM 的吞吐只有 FP4 的一半（FP8）或更低（BF16），且这部分激活的显存与带宽不享受 4 倍压缩。整体加速比因此受 Amdahl 限制：设 FFN 与投影占 GEMM 时间的比例为 p，则理论上限加速比约为 1/((1-p) + p/2)（FP4 相对 FP8 吞吐 2 倍）。p 越大越接近 2 倍，p 越小越被注意力拖住。这就是为什么该算法的适用边界被写成「计算受限的 FFN 与投影 GEMM」——它不是全模型量化方案，而是分层精度方案。</p>\n<p>具体例子：一个 DiT block 内，QKV 投影与 FFN 的 GEMM 走 NVFP4，QK<sup>T</sup> 与 PV 走 FP8，LayerNorm 与残差保持 BF16。输出经缩放还原后进 LayerNorm，残差通路把 BF16 的原始输入加回来，这一步同时起到误差缓冲作用：FP4 引入的偏差在残差加法中被部分抵消，而不是直接串进下一层。VAE 解码前对最后一层输出做 BF16 反量化与 bias 校正，是把 4 位误差挡在像素域之外的最后一道闸。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-18\">十八 · 残差补偿与 bias 校正的可实现形式</h3>\n<p>给定事实提到「仅保留 FP8 残差用于误差补偿」与「VAE 前做 bias 校正」。这两件事在实现上是两个不同层级的补偿。残差补偿在 GEMM 输出侧：量化后的权重 Ŵ 与原始 W 之差为 R = W − Ŵ，把 R 以 FP8 存储（不参与 FP4 MMA），在部分和还原后用一个低秩或逐通道的 FP8 GEMM 把 R·X 加回去。伪代码上它是一次并行的、位宽更高的修正 GEMM，其开销远小于把主 GEMM 提回 FP8，但能把系统性偏差压下去。关键在于 R 的幅值远小于 W，FP8 足以表达，且 R 的分布比 W 更接近零均值，量化误差不累积。</p>\n<p>bias 校正在输出侧、VAE 之前：对最后一层输出统计其在校准集上的均值偏移，用一个逐通道的 BF16 bias 向量在反量化时减掉。它针对的是量化引入的直流偏置——per-token 缩放的舍入在大量 token 上平均后不一定为零，这个非零均值进入 VAE 会被放大成可见的色偏或亮度漂移。bias 校正的成本是一次逐通道加法，几乎可忽略，但它要求校准集覆盖目标视频的亮度分布；校准集偏差会放大时空注意力误差，这是给定事实里点明的代价。</p>\n<p>代价面：残差补偿多了一次 GEMM，虽然位宽低、规模小，但在 FFN 占主导的层里它会把 FP4 的吞吐收益削掉一部分；若残差 GEMM 与主 GEMM 不能重叠，它就在关键路径上。工程判断是：只在 Δ<sub>rel</sub> 估计值逼近上界的层启用残差补偿，其余层省略，用逐层开关换取整体吞吐。这与精度分配是同一套思路——静态量化方案的效果取决于逐层的误差预算分配，而不是全局统一策略。</p>\n<p>具体例子：某 FFN 层权重重尾明显，离线算出的 Δ<sub>rel</sub> 接近上界，则该层启用 FP8 残差补偿 GEMM；相邻的投影层权重分布均匀，Δ<sub>rel</sub> 远低于上界，直接走纯 FP4 不补偿。两层在同一个 DiT block 内共存，kernel 调度上表现为一次 FP4 GEMM 加一次可选的小 FP8 GEMM，后者是否发射由离线元数据里的标志位决定，运行时零分支判断开销。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-19\">十九 · 从公式到 kernel 参数：块大小、tile 与 occupancy 的联动</h3>\n<p>公式里的 16 元素分组不是随便定的，它同时是量化粒度和 kernel 内缩放复用的单位。分组越小，Δ<sub>rel</sub> 上界越紧（离群值污染范围窄），但 scale 缓冲越大、每 tile 的缩放还原指令越多；分组越大，scale 开销降，但块内动态范围失控。16 是在 E4M3 微缩放能表达块内幅值、且一个 MMA tile 的 K 维能整除 16 的前提下取的折中。工程上若把分组改到 32，scale 读取减半，但重尾层的 Δ<sub>rel</sub> 会明显恶化，需要更多层退回 FP8，反而损失吞吐。</p>\n<p>tile 形状与 occupancy 的联动是第二个关键。FP4 输入使共享内存中的操作数位宽降为 BF16 的 1/4，理论上可以放大 tile 以提升数据复用；但 FP32 累加器不缩水，寄存器压力随 tile 面积增长。设每线程累加器元素数为 a，寄存器上限为 R，则 tile 面积受 a ≤ R 约束，occupancy 又受寄存器总数与共享内存共同限制。低 batch 时 occupancy 上不去，scale 加载延迟无法被 warp 切换掩盖，这正是失败模式之二的量化根源。可行的调参方向是缩小 K 维 tile 以降低单次 scale 加载的等待深度，同时保持 M/N tile 足够大以维持 MMA 效率。</p>\n<p>代价面：权重显存降至 BF16 的约 1/4，B200 的 HBM3e 带宽下 DiT 每步权重读取时间近似线性下降，长视频高分辨率 latent 的 batch 上限随之提升——这是显存与带宽侧的收益，与 GEMM 吞吐侧的 2 倍收益是两笔独立的账，不能相乘。端到端时延由两者中较慢的一侧决定：若某步是带宽受限（权重读取主导），则 4 倍压缩直接兑现；若某步是计算受限（FFN GEMM 主导），则兑现的是 2 倍吞吐；注意力段两者都不兑现。容量规划时必须按段拆开算，而不是给整个模型套一个加速比。</p>\n<p>最后落到一个具体判断：该算法的稳定性不取决于 FP4 本身，而取决于三件事是否同时成立——per-token amax 在目标视频的运动分布上足够平稳、注意力与残差保留在 FP8/BF16、VAE 前有 bias 校正。任一条不成立，误差就会以闪烁或条带的形式穿透到像素域，而此时再调 kernel 参数也救不回来，因为问题出在数值预算分配而非调度。</p>\n<h3 id=\"alg-nvfp4-video-dit-sec-20\">二十 · 请求形态：什么样的负载吃到 NVFP4 的红利</h3>\n<p>NVFP4 视频 DiT 的收益结构由 GEMM 的形状决定，而不是由模型名决定。该算法把 FFN 与投影的权重和激活压到 E2M1，注意力 QK^T/PV 保留 FP8 或 BF16，因此一次前向里真正跑在 FP4 张量核心上的，是那些 <em>M 足够大、K 足够深</em> 的线性层。请求形态必须能把这两维喂饱：高分辨率长视频 latent 的批量去噪，正是把 M 维（token 块数 × batch）撑起来的形态。反过来，单条短视频、单帧编辑、逐帧交互式预览这类请求，M 维被压到很小，FP4 kernel 的 tile 填不满，两级缩放的 scale 加载与反量化指令成为主导项。</p>\n<p>长度分布是第二个筛选器。潜变量序列长度随分辨率与帧数近似平方/线性增长，序列越长，DiT 每步的 GEMM 越偏向计算受限，权重带宽下降（BF16 的约 1/4）带来的每步权重读取时间缩短才真正体现在端到端时延上。中等长度、单条请求的负载处在带宽与指令开销的交叉区，收益最不稳定。工程上判断一个负载是否适配，看的不是“视频”这个标签，而是 <em>每步去噪的 GEMM 平均 M 与 K</em>：M 由 batch×token 块给出，K 由隐层宽度给出，K 通常固定且足够深，所以配方实际调的是 M。</p>\n<div class=\"formula\">$$\\text{FP4 有效利用率}\\;\\approx\\;\\frac{M}{M_{\\text{tile}}}\\cdot\\frac{1}{1+\\alpha\\cdot\\frac{N_{\\text{scale}}}{M\\cdot K}},\\qquad \\alpha\\ \\text{为每块 scale 加载与反量化的指令当量}$$</div>\n<p>这个式子只做定性用途：当 M 接近或超过 kernel tile 高度时，第二项趋于可忽略；当 M 掉到 tile 高度以下，分母里的 scale 开销按块数摊到更少的有效乘加上，加速比被 Amdahl 式地压住。举例：一条 720p、数十帧的 latent 序列在 batch=1 时，FFN 的 M 往往只有数千 token 块量级，尚可；若切成更小的 patch 块或做逐帧独立去噪，M 掉一个数量级，FP4 的吞吐优势就被反量化指令吃掉。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-21\">二十一 · 批大小：被激活显存与 kernel 效率双向夹住</h3>\n<p>批大小在 NVFP4 配方里不是一个自由参数，而是被两条约束同时夹住。上界来自激活显存：虽然权重降到 BF16 的 1/4，但 LayerNorm、残差、注意力 QKV 的 FP8/BF16 副本、以及时空注意力的中间张量仍按高精度驻留，batch 增大时这部分线性增长，先于权重触顶。下界来自 FP4 kernel 效率：M 太小时 tile 空转，两级缩放的 per-block scale 读取与反量化指令摊不薄。</p>\n<p>因此存在一个“有效批窗口”，窗口内每步去噪时延随 batch 近似线性增长（吞吐线性上升），窗口外则出现两种病态：batch 过大时显存换页或触发重算，单步时延跳变；batch 过小时单步时延不降反升——因为固定开销（scale 加载、kernel launch、反量化）不随 M 缩小。校准这个窗口的办法是扫 batch 看每步时延曲线，找拐点，而不是照搬别的模型的推荐值。注意激活量化的粒度是 per-token 块，batch 变化会改变跨帧 amax 的统计分布，同一校准集在不同 batch 下给出的 scale 并不等价，这一点在调窗口时必须一起固定。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>M 维特征</th><th>主要瓶颈</th><th>配方动作</th></tr></thead><tbody><tr><td>高分辨率长视频批量去噪</td><td>大且稳定</td><td>激活显存、注意力精度保留</td><td>取窗口上沿，注意力锁 FP8/BF16</td></tr><tr><td>中等长度单条请求</td><td>中等、随帧数波动</td><td>带宽与指令开销交叉</td><td>合并请求成批，避免逐帧独立</td></tr><tr><td>短视频/交互预览</td><td>小</td><td>反量化与 scale 加载</td><td>退回 FP8 路径或提高并发聚合</td></tr></tbody></table>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-22\">二十二 · 并发与连续批处理：聚合是配方的另一半</h3>\n<p>服务侧的并发不是把 batch 直接拉大，而是把多个请求的去噪步在时间轴上聚合。视频 DiT 的去噪是固定步数的迭代，每步都是一次完整的 DiT 前向，天然适合连续批处理：新请求在步边界插入，完成的请求在步边界退出。对 NVFP4 而言，这种聚合的价值在于把单条请求的小 M 拼成跨请求的大 M，让 FP4 kernel 的 tile 被填满，同时把 scale 加载的固定开销摊到更多有效乘加上。代价是步同步：批内最慢的请求决定该步的完成时间，长度分布越散，同步损失越大。</p>\n<p>这里有一个与精度耦合的细节：per-token 块量化按 token 统计 amax，跨请求拼接后同一 GEMM 内的 token 来自不同视频、不同帧、不同运动强度，amax 分布被拉宽。若沿用单请求校准得到的 scale，运动剧烈片段的 token 会被系统性压小有效动态范围，误差在后续层累积。配方上要么按请求分组做 GEMM（牺牲聚合度），要么在拼接时对每组 token 独立量化并在输出端按组还原——后者是保持聚合度又控制误差的常规做法，代价是输出反量化多一次分组缩放乘法。</p>\n<ul><li>机制：步边界插入/退出，按 token 组独立量化，输出按组还原。</li><li>代价：批内同步使每步时延取 max，长度分布方差直接转化为吞吐损失。</li><li>例子：混合长短视频请求时，把长请求与若干短请求编入同批，短请求在步边界快速轮转，长请求持续占用 M 维，窗口利用率最高。</li></ul>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-23\">二十三 · 负载不对时的三种病态</h3>\n<p>第一种是低 batch / 小 GEMM 下的负加速。两级缩放的每次 GEMM 都要读 per-block E4M3 微缩放与 per-tensor FP32 二级缩放，再在 SM 上做反量化，这些指令量与 M 无关。M 掉下去后，FP4 张量核心的吞吐优势（约为 FP8 的 2 倍）被固定开销抵消，端到端时延不降反升。判断信号很直接：把同一负载的 FP8 与 NVFP4 两条路径并排跑，若 NVFP4 的每步时延高于 FP8，说明负载落在窗口下界之外，应提高并发聚合或退回 FP8。</p>\n<p>第二种是运动剧烈片段的量化误差累积。视频激活跨帧动态范围大，per-token 块量化在快速运动、高对比边缘处 amax 跳变，E2M1 只有 4 个尾数位，块内动态范围一旦被单个离群值主导，其余元素的相对误差被放大。误差不在此层终止，而是随残差流进入后续块，最终在 VAE 解码端表现为闪烁与条带。配方上的对策是精度分配而非全局降精度：注意力 QK^T 与 PV 保持 FP8/BF16，残差与 LayerNorm 保持 BF16，VAE 解码前对最后一层输出做 BF16 反量化与 bias 校正，把 4bit 误差挡在像素域之外。</p>\n<p>第三种是把注意力也压到 FP4。注意力 logits 对量化极敏感，QK^T 的误差经 softmax 放大后使注意力图失真，稀疏区与稠密区同时出现结构崩坏，且这种崩坏不随 batch 增大而缓解——它是精度分配错误，不是负载问题。这也是为什么该算法的适用边界明确写在“计算受限的 FFN 与投影 GEMM”上：越过这条线，收益与画质同时失控。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-24\">二十四 · 配方与 SLO 的对接</h3>\n<p>该算法的 SLO 以每步去噪时延与端到端帧输出为主，而不是单请求首帧时延。这意味着容量规划要按“步”而不是按“请求”做单位：每步的时延由该步批内最大 M 与注意力精度路径共同决定，端到端时延是步数乘以每步时延再加 VAE 解码。少步蒸馏会压缩步数，从而放大单步时延在端到端中的权重，此时低 batch 的固定开销占比更高，配方更应偏向聚合。</p>\n<p>规划时的可操作量有三个：窗口内的目标 batch、每步的激活显存占用、以及注意力路径的精度档位。权重显存已降至 BF16 的约 1/4，不再是长视频 batch 上限的主约束；真正的约束是激活与注意力中间张量。因此扩容顺序是先提并发聚合度、再提单批 batch、最后才考虑把注意力往更低精度推——最后一步在画质上不可逆。整体加速比受注意力与残差保留 FP8/BF16 的 Amdahl 限制，这条上限不会因为 FP4 kernel 更快而移动，配方只能在剩余部分里榨取。</p>\n<div class=\"formula\">$$T_{\\text{step}}\\;\\approx\\;\\max\\!\\Big(T_{\\text{FP4,FFN}}(M),\\;T_{\\text{attn,FP8}}(M)\\Big)+T_{\\text{deq}}(M),\\qquad T_{\\text{deq}}\\ \\text{与 }M\\ \\text{弱相关}$$</div>\n<p>把这条式子读成工程判断：当 FFN 的 FP4 时延已经降到注意力 FP8 时延之下，继续优化 FFN 的量化没有意义，瓶颈在注意力；当反量化项在小 M 下超过两项之和，瓶颈在固定开销，应聚合而非调精度。配方的好坏最终体现在能否让这三项在同一批内接近平衡，而不是把任何单项推到极致。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-25\">二十五 · 负载配方：批量去噪才回本，小 GEMM 与剧烈运动是两道坎</h3>\n<p>这套 NVFP4 方案的收益结构不是均匀的，它把赌注押在“每步去噪的 GEMM 足够大、批足够厚”上。权重预打包为 16 元素共享 E4M3 微缩放、块间 FP32 全局缩放的 NVFP4 块布局，激活按 token 块统计 amax 后动态量化，两者在 SM100 FP4 MMA 上直接相乘、FP32 累加。问题在于，每一层 GEMM 之前都要读缩放因子、执行反量化指令，这部分开销与 GEMM 的算术强度无关，只与调用次数和批的形状有关。当批大小被激活显存压到很小、或潜变量序列被切碎成小 GEMM 时，scale 加载与反量化指令的固定成本摊不开，Amdahl 意义上的串行段占比上升，端到端每步时延不降反升——这是该方案最典型的失效条件，也是容量规划时必须先算清的一笔账。</p>\n<p>把代价写成可核对的量：设单层 GEMM 的 FP4 计算时间为 $T_{\\text{gemm}}$，反量化与 scale 读取的固定开销为 $T_{\\text{deq}}$，则该层有效加速比受限于</p>\n<div class=\"formula\">$$S_{\\text{eff}}=\\frac{T_{\\text{BF16}}}{T_{\\text{gemm}}+T_{\\text{deq}}},\\qquad T_{\\text{deq}}\\ \\text{与批大小近似无关}$$</div>\n<p>批越大，$T_{\\text{gemm}}$ 线性增长而 $T_{\\text{deq}}$ 基本不变，$S_{\\text{eff}}$ 才逼近 FP4 张量核心相对 FP8 约 2 倍的吞吐优势与权重带宽降至 BF16 约 1/4 的收益。反过来，若注意力与残差仍保留 FP8/BF16（这是精度分配的硬约束，QK^T 与 PV 对 logits 误差敏感，不能压到 FP4），则整体加速比还被这段不可量化的部分按 Amdahl 定律封顶，批再大也越不过去。因此负载配方的第一条判断是：请求必须是高分辨率长视频 latent 的批量去噪，批大小由激活显存与 FP4 kernel 效率共同约束，落在“GEMM 够大、激活装得下”的窗口内，而不是单条短请求的低延迟场景。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>GEMM 规模</th><th>主要瓶颈</th><th>方案表现</th></tr></thead><tbody><tr><td>长视频高分辨率、批量去噪</td><td>大，批厚</td><td>FP4 吞吐与权重带宽</td><td>收益兑现，batch 上限因权重显存降至约 1/4 而提升</td></tr><tr><td>低 batch / 小 GEMM</td><td>小</td><td>反量化指令与 scale 访存延迟</td><td>开销抵消收益，时延不降反升</td></tr><tr><td>运动剧烈片段</td><td>大</td><td>per-token 量化误差</td><td>误差累积至 VAE 解码端，闪烁与条带</td></tr></tbody></table>\n<p>第二道坎在长度分布与内容分布上。视频激活跨帧动态范围大，per-token 块量化按 token 统计 amax 才能适应这种跨帧漂移；一旦校准集偏向静态场景，运动剧烈片段的 per-token 量化误差就会上升，误差沿 DiT 块累积，最终在 VAE 解码端表现为闪烁与条带——像素域的观感退化不会在中间层指标上提前暴露。工程上的对策是把精度分配做成内容相关的：对运动剧烈片段保留注意力与残差为 FP8/BF16，VAE 解码前对最后一层输出做 BF16 反量化与 bias 校正，阻断 4bit 误差进入像素域。这意味着负载配方不能只看平均长度，还要看长度与运动的联合分布：一条长而平缓的请求与一条短而剧烈的请求，走的可能是不同的精度路径与不同的 SLO 预算。容量规划时按“每步去噪时延 + 端到端帧输出”双指标定 SLO，并为剧烈运动样本预留 BF16 回退的算力余量，否则峰值负载下闪烁投诉会集中爆发在少数请求上。</p>\n<p>最后一条边界是拓扑：该方案以单卡内 GEMM 流水为主，依赖原生 FP4 张量核心与 HBM3e 带宽，KV 保持 BF16 或 FP8 以维持注意力精度。跨卡扩展时，权重读取时间的线性下降只发生在单卡内，通信与注意力段不随 FP4 缩放，因此多卡并行的收益曲线比单卡更早变平。判断是否上这套方案，先看单卡批量去噪能否把批堆到 GEMM 摊薄反量化开销的阈值之上；堆不上去，就该退回 FP8 路径，而不是指望 FP4 的峰值吞吐救场。</p>\n<h3 id=\"alg-nvfp4-video-dit-sec-26\">二十六 · 硬件档位：FP4 原生档与“可跑但不划算”档</h3>\n<p>部署 NVFP4 视频 DiT 的第一道判断不是“量化方案选什么”，而是“这台机器有没有原生 FP4 通路”。SM100/SM103 的 tcgen05 FP4 MMA 与 HBM3e 带宽是这套算法的两个物理前提：前者决定 GEMM 吞吐上限，后者决定权重读取时间。B200/GB200 单卡满足这两个前提；而通过 PCIe 挂接的上一代加速卡即使能靠软件模拟 E2M1 反量化跑通，也会因为缺少原生 FP4 张量核心指令而退化为一串 BF16 乘加加移位，收益被指令开销吃掉。工程上把档位划成三档：原生 FP4 + HBM3e（目标档）、原生 FP4 + 较低带宽（权重带宽收益打折，长视频 batch 上限受限）、无原生 FP4（仅供精度验证，不作部署）。</p>\n<p>档位判断要落到一个可测的量上：单步去噪的权重读取时间。设第 $l$ 层权重元素数为 $N_l$，BF16 下每元素 2 字节，NVFP4 下每 16 元素共享一个 E4M3 微缩放（1 字节）加一个 per-tensor FP32 全局缩放，摊到每元素约 0.5 + 1/16 字节。于是单步权重读取时间近似为</p>\n<div class=\"formula\">$$T_{\\text{w}}=\\frac{\\sum_l N_l \\cdot b_{\\text{eff}}}{B_{\\text{HBM}}},\\quad b_{\\text{eff}}^{\\text{BF16}}=2,\\; b_{\\text{eff}}^{\\text{NVFP4}}\\approx 0.5625$$</div>\n<p>分子随量化线性缩小，分母由档位决定。这条式子给出的是“理论上限”，实际能否兑现取决于 kernel 是否真的把缩放因子读取与反量化融进 MMA 流水——若 scale 加载走独立指令且未与 MMA 重叠，$T_{\\text{w}}$ 的下降会被 SM 指令周期抵消。判断档位是否值得上 NVFP4，就看实测单步时延是否跟随 $b_{\\text{eff}}$ 的比例下降；若下降幅度明显小于 3.5 倍，说明瓶颈已从带宽转到指令或注意力侧。</p>\n<p>具体例子：一个以 FFN 与投影为主干的长视频 DiT，在原生 FP4 档上把权重压到 BF16 的约 1/4，单步权重读取时间近似线性下降，从而把高分辨率 latent 的 batch 上限抬起来；同一模型在无原生 FP4 档上跑，反量化指令占满 SM 而 MMA 吞吐没变，端到端时延不降反升，这正是 Amdahl 限制的典型表现。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-27\">二十七 · 并行拓扑：单卡 GEMM 流水优先，跨卡只切序列与 batch</h3>\n<p>这套算法的并行拓扑有一个明确取向：优先在单卡内把 GEMM 流水打满，而不是一上来就做张量并行。原因是 NVFP4 的收益来自权重带宽与 FP4 吞吐，切分权重会把每张卡上的 GEMM 变小，两级缩放的反量化与 scale 加载开销占比上升，低占用小 GEMM 恰恰是这套算法最不划算的形态。因此拓扑的第一层是单卡：一个 DiT block 内的 QKV/FFN 投影连续下发，激活按 token 块动态量化后直接进 FP4 MMA，累加器 FP32，输出反量化回 BF16 写回，LayerNorm 与残差保持 BF16 不参与量化。</p>\n<p>第二层才是跨卡。视频 DiT 的序列维是 latent patch 数，天然可按帧块或 patch 块切分，序列并行比张量并行更契合：每张卡持有完整权重、只处理一段 latent token，权重读取在每张卡上重复但 GEMM 形状不变，FP4 kernel 效率不受损。批维切分用于吞吐扩展，配合连续批处理把不同分辨率、不同帧数的请求拼进同一 batch，代价是 per-token amax 统计要按各自 token 块独立做，不能跨请求混算。</p>\n<p>拓扑选择的代价可以直接算：设单卡 FP4 GEMM 有效吞吐为 $P_4$，注意力与残差仍走 FP8/BF16 的部分耗时为 $T_{\\text{attn}}$，则单步时延下界为</p>\n<div class=\"formula\">$$T_{\\text{step}}\\ge \\max\\!\\left(\\frac{\\sum_l \\text{FLOPs}_l}{P_4},\\;T_{\\text{attn}}\\right)+\\varepsilon_{\\text{deq}}$$</div>\n<p>$\\varepsilon_{\\text{deq}}$ 是反量化与缩放因子读取的不可重叠部分。序列并行把第一项按卡数摊薄，但第二项 $T_{\\text{attn}}$ 不随卡数下降——注意力精度保留在 FP8/BF16，它构成并行扩展的硬底。这就是为什么拓扑要先确认注意力侧能否被时空注意力的分块与稀疏化压下去，否则加卡只摊薄了 FFN 而端到端时延卡在注意力上。</p>\n<p>具体例子：GB200 NVL72 机架内做序列并行时，NVLink 5 域内的 all-to-all 用于注意力前后重排 latent 分块，通信量与 token 数成正比而非与权重成正比，因此不会像张量并行那样每层都触发大块 all-reduce；把 FFN 留在单卡、只切序列，是这套算法在机架尺度上较稳的拓扑。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-28\">二十八 · 量化方案：静态权重 + 动态激活 + 精度保留清单</h3>\n<p>量化方案在部署上不是“全 FP4”一个开关，而是一张精度分配表。权重走离线静态量化：每 16 元素一组求 E4M3 微缩放，再求 per-tensor FP32 全局缩放，打包成 NVFP4 块布局，推理时只读不重算。激活走在线动态量化：进入 QKV/FFN 前按 token 块统计 amax 再量化，因为视频激活跨帧动态范围大，per-tensor 静态激活缩放会在运动剧烈片段上崩掉。两级缩放的还原式为</p>\n<div class=\"formula\">$$w\\approx s_{\\text{FP32}}\\cdot s_{\\text{E4M3}}^{(g)}\\cdot q_{\\text{E2M1}},\\qquad \\hat{W}_i=s_{\\text{blk},i}\\cdot s_{\\text{glob}}\\cdot \\mathrm{deq}(W_i^{\\text{FP4}})$$</div>\n<p>精度保留清单是部署配方里最不能省的一栏：注意力中 QK^T 与 PV 走 FP8 或 BF16，因为 FP4 对 logits 误差敏感，压到 FP4 会让注意力图失真、稀疏与稠密区域同时结构崩坏；LayerNorm 与残差保持 BF16，避免归一化统计被 4bit 噪声污染；VAE 解码前对最后一层输出做 BF16 反量化并加 bias 校正，阻断 4bit 误差进入像素域造成闪烁与条带。这份清单意味着端到端加速比受 Amdahl 限制，FFN 与投影的 FP4 收益会被注意力与残差段稀释。</p>\n<p>部署上还要给出校准策略的可复现口径：per-token 块量化的 amax 统计必须覆盖跨帧动态范围，校准集要包含运动剧烈片段而非只取静态镜头，否则校准偏差会放大时空注意力误差。校准集偏差的代价不是精度指标上的小数点，而是长视频里肉眼可见的闪烁，属于必须在上线前用片段级抽检拦住的失败模式。</p>\n<p>具体例子：同一段高运动长视频，若把 QKV 也压到 NVFP4，注意力 logits 误差使稠密区域出现结构崩坏；而按清单把 QKV 留在 FP8、仅 FFN 与投影走 FP4，端到端 FVD 退化被压在可接受范围，代价是单步时延里注意力段占比上升，这也解释了为什么拓扑扩展要先解决注意力侧。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-29\">二十九 · KV 与中间激活策略：BF16/FP8 保精度，按需回写 HBM</h3>\n<p>视频 DiT 的“KV”与语言模型不同：它没有自回归 KV cache 的逐 token 增长，但有跨去噪步的中间激活与注意力工作集。部署配方里这一栏的原则是：KV 与中间激活保持 BF16 或 FP8 以维持注意力精度，仅保留 FP8 残差用于误差补偿；中间激活按需回写 HBM，而不是全部常驻。原因是 FP4 只用在 GEMM 输入侧，注意力工作集若也压到 4bit，logits 误差会直接破坏注意力图，与第三节的精度保留清单冲突。</p>\n<p>显存账要按 batch 与序列长度算。设单请求 latent token 数为 $S$、隐藏维 $d$、层数 $L$、每元素字节 $b$，注意力工作集显存近似为</p>\n<div class=\"formula\">$$M_{\\text{act}}\\approx B\\cdot S\\cdot d\\cdot L\\cdot b_{\\text{act}},\\quad b_{\\text{act}}^{\\text{BF16}}=2,\\;b_{\\text{act}}^{\\text{FP8}}=1$$</div>\n<p>权重侧因 NVFP4 降到 BF16 的约 1/4，$M_{\\text{act}}$ 就成为 batch 上限的主约束。把中间激活按需回写 HBM 而不是全驻留，是用带宽换显存：回写与重读的代价计入单步时延，但换来更大的 batch，而 batch 又是 FP4 kernel 效率的前提——低 batch 下反量化开销占比高、加速比受 Amdahl 限制。这是一个必须一起调的耦合参数，不能单独调 batch 或单独调回写策略。</p>\n<p>具体例子：长视频高分辨率 latent 在 BF16 下激活显存把 batch 压到很小，FP4 权重腾出的显存被用来抬 batch；若同时把中间激活从 BF16 降到 FP8，$M_{\\text{act}}$ 减半，batch 进一步上升，但注意力精度需要靠残差补偿与 VAE 前 bias 校正兜住，否则闪烁风险回升。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-30\">三十 · 调度参数：以每步去噪时延为 SLO 的批调度</h3>\n<p>调度参数围绕一个 SLO 展开：每步去噪时延与端到端帧输出。视频请求的形态是高分辨率长视频 latent 的批量去噪，步数是固定的采样步数，因此调度器的基本单位是“步”而不是“token”。连续批处理在这里的含义是：在一个去噪步内把多个请求的 latent 拼成一个大 batch 送进 FP4 GEMM，步与步之间允许新请求插入，但插入点要放在步边界，避免半步插入导致 per-token amax 统计与 batch 形状抖动。</p>\n<p>调度参数的可复现思路是三步定参。第一步定 batch 下界：由 FP4 kernel 效率曲线找出反量化开销不再主导的最小 batch，低于它就不上 NVFP4 而退回 FP8。第二步定 batch 上界：由 $M_{\\text{act}}$ 与权重显存之和不超过 HBM 容量、且单步时延满足 SLO 共同决定。第三步定抢占与优先级：长视频请求步数多、占用显存久，用帧数或 latent token 数做配额，防止单个长请求把 batch 槽位占满导致短请求排队超时。</p>\n<p>调度代价可以用一个简单的不等式表达：设单步时延预算为 $T_{\\text{SLO}}$，单请求单步耗时为 $t$，则并行请求数 $n$ 受</p>\n<div class=\"formula\">$$n\\le \\left\\lfloor \\frac{T_{\\text{SLO}}}{t}\\right\\rfloor,\\qquad t=t_{\\text{gemm}}(B)+t_{\\text{attn}}(B)+\\varepsilon_{\\text{deq}}(B)$$</div>\n<p>关键在 $\\varepsilon_{\\text{deq}}(B)$ 随 $B$ 增大而被摊薄，$t_{\\text{gemm}}$ 随 $B$ 增大而趋近饱和，因此 $n$ 存在一个由显存而非时延决定的实际上界。调度器要做的不是把 $n$ 推到最大，而是把 $B$ 稳定在“反量化开销已摊薄、显存未触顶”的区间内，避免 batch 在步边界上大幅跳变引起 kernel 效率抖动。</p>\n<p>具体例子：一批混合分辨率的视频请求，短请求步数少、长请求步数多，若按先到先服务，长请求会把 batch 长期占住而短请求在队列里等过 SLO；按 latent token 配额调度后，每步的 batch 形状稳定，FP4 GEMM 的 scale 加载与反量化开销被稳定摊薄，端到端帧输出时延的方差明显收窄。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-31\">三十一 · 可复现配置思路：从档位到参数的判定链</h3>\n<p>把前五节收成一条可复现的判定链，顺序不能颠倒，因为每一步都在缩小下一步的可行域。第一，确认硬件档位：是否有原生 FP4 张量核心与 HBM3e 带宽，无原生 FP4 则直接退出 NVFP4 部署路径，只保留精度验证。第二，确认精度保留清单：注意力 QK^T/PV 走 FP8 或 BF16、LayerNorm 与残差 BF16、VAE 前 BF16 反量化加 bias 校正，据此估算 Amdahl 上限，判断端到端加速比的天花板在哪里。第三，定并行拓扑：单卡 GEMM 流水优先，跨卡只切序列与 batch，先确认注意力侧耗时是否已成为硬底。第四，定 KV 与中间激活策略：BF16/FP8 保精度、按需回写 HBM，用带宽换显存抬 batch。第五，定调度参数：以每步去噪时延为 SLO，在反量化摊薄点与显存触顶点之间锁定 batch 区间。</p>\n<p>这条链上每一步都有一个可测的判据，而不是靠调参试出来。档位判据是实测单步时延是否跟随 $b_{\\text{eff}}$ 比例下降；精度判据是片段级抽检有无闪烁与条带；拓扑判据是加卡后 $T_{\\text{step}}$ 是否仍被 $T_{\\text{attn}}$ 卡住；显存判据是 $M_{\\text{act}}$ 与权重之和是否逼近 HBM 容量；调度判据是 batch 在步边界上的跳变幅度是否引起 kernel 效率抖动。任何一个判据不满足，就回退到上一档配置，而不是在同一档上继续压参数。</p>\n<p>失败模式的拦截点也在这条链上：运动剧烈片段 per-token 量化误差上升导致闪烁，拦截点在第二、四步的精度保留与校准集覆盖；低 batch 下反量化开销使加速比受 Amdahl 限制，拦截点在第一步的档位判断与第五步的 batch 下界；注意力压到 FP4 导致注意力图失真，拦截点在第二步的精度保留清单。把这三类失败模式映射到判定链的具体步骤，比在上线后靠监控指标回溯要省得多。</p>\n<p>最后落在一个工程判断上：这套算法的部署收益不是“全模型 4bit”带来的，而是“FFN 与投影的 FP4 GEMM 在足够大的稳定 batch 下把权重带宽与 MMA 吞吐吃满”带来的。因此配置思路的核心不是把量化推到极限，而是把 batch 稳定在反量化开销已摊薄、注意力精度仍被保留的那个窄区间里——档位、拓扑、精度清单、KV 策略、调度参数五者共同定义了这个区间，任何一项单独调优都会把区间推歪。</p>\n<h3 id=\"alg-nvfp4-video-dit-sec-32\">三十二 · 显存账本：权重、激活与潜变量的三段占用</h3>\n<p>把NVFP4推理的显存拆开看，DiT单步驻留的并不是一个数，而是三段互相挤压的账：权重段、激活段、潜变量与残差段。权重按16元素共享E4M3微缩放、块间FP32全局缩放打包后，每元素4bit加缩放开销，相对BF16的压缩比接近4倍，这是本算法最确定的收益；它直接决定了单卡能放多宽的DiT、能开多大的批。激活段则是变量：QKV/FFN入口按token块动态量化为NVFP4，但LayerNorm、残差、以及注意力中的QK^T与PV保留FP8/BF16，这部分不随量化缩小，反而随分辨率与帧数线性膨胀。潜变量段最容易被低估——高分辨率长视频的latent序列在时间维上展开后，单个请求的token数就足以吃掉可观的HBM，批一上来，激活与潜变量先于权重触顶。</p>\n<p>设权重元素数$N_w$、单请求激活元素数$N_a$、潜变量元素数$N_z$，批大小$B$，则驻留显存可写成</p>\n<div class=\"formula\">$$M \\approx \\underbrace{0.5N_w}_{\\text{NVFP4权重+scale}} + B\\cdot\\underbrace{\\left(\\alpha N_a + \\beta N_z\\right)}_{\\text{混合精度激活与潜变量}}$$</div>\n<p>其中$\\alpha,\\beta$由精度分配决定：走FP4的FFN/投影取0.5字节每元素，保留BF16的残差与注意力取2字节。工程含义很直接——权重段是常数，批扩展的边际成本全在$\\alpha N_a+\\beta N_z$上。一个具体例子：同一张B200上把FFN与投影全部NVFP4化后，权重腾出的空间并不会自动变成更大的batch，因为每加一个长视频请求，激活与潜变量的增量由保留精度的那部分主导；容量规划要按“每请求激活字节”而非“每请求权重字节”做除法，否则会在压力测试里发现batch上限远低于按权重压缩比推算的值。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-33\">三十三 · 带宽与反量化的Amdahl边界</h3>\n<p>权重带宽降至BF16的1/4，意味着DiT每步的权重读取时间近似线性下降——在B200的HBM3e带宽下，原本被权重流支配的GEMM会从带宽受限转向计算受限，这正是FP4张量核心吞吐约为FP8两倍得以兑现的前提。但端到端每步时延不是权重时间的单调函数。反量化与缩放因子读取引入额外SM指令：每个16元素块要取一次E4M3微缩放、每个张量取一次FP32全局缩放，再在MMA前完成deq。低占用、小batch时，这些指令与scale加载的访存延迟无法被GEMM的算力掩盖，收益被吃掉。用Amdahl形式写出加速比上界：</p>\n<div class=\"formula\">$$S_{\\text{e2e}} \\le \\frac{1}{f_{\\text{FP4}}/S_{\\text{FP4}} + f_{\\text{attn}}/S_{\\text{attn}} + f_{\\text{deq}}}$$</div>\n<p>$f_{\\text{FP4}}$是FFN与投影占比，$S_{\\text{FP4}}$接近2；$f_{\\text{attn}}$是保留FP8/BF16的注意力与残差占比，$S_{\\text{attn}}$接近1；$f_{\\text{deq}}$是反量化与scale加载的相对开销，在小GEMM下不可忽略。这条式子解释了失败模式：低batch或小GEMM场景下$f_{\\text{deq}}$上升、$f_{\\text{FP4}}$的有效收益被摊薄，端到端时延不降反升。具体例子：单请求短片段去噪时，FFN的GEMM尺寸小到无法让FP4 kernel进入稳态，两级缩放的指令开销在每步里固定支出，此时把批拉起来比换精度更有效——批是摊薄$f_{\\text{deq}}$的手段，也是让FP4 kernel效率达标的门槛。</p>\n<p>带宽侧还有一个隐性代价：KV与中间激活按需回写HBM，仅保留FP8残差用于误差补偿。残差本身占带宽，且回写与读取发生在LayerNorm与时空注意力之间，形成额外的往返流量。长视频高分辨率下，这部分流量随token数增长，若与权重流在同一时间窗竞争HBM，实测带宽利用率会被拉满而GEMM等数据。工程判断是：把残差补偿的粒度与回写时机对齐到块边界，避免每层都触发一次全量往返。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-34\">三十四 · 通信：单卡GEMM流水之外的规模瓶颈</h3>\n<p>本算法的并行拓扑以单卡内GEMM流水为主，这意味着它的通信代价在单卡档位上接近于零，规模上去后瓶颈不在NVLink 5的带宽，而在“什么时候不得不跨卡”。当单卡显存装不下长视频latent序列的批时，序列并行或张量并行成为唯一出路，此时每步去噪都要在层边界做激活的all-reduce或all-gather。NVFP4激活在跨卡传输前若保持4bit，通信量是BF16的1/4，但接收端需要重新组装缩放因子并做反量化，通信省下的时间可能被接收侧的deq指令吃掉；若在发送前反量化回BF16再传，通信量回到原样，压缩收益归零。这是一个必须显式选择的取舍点，而不是自动生效的优化。</p>\n<p>用每步通信量估算：设单层激活元素$N_l$、并行度$P$、每步跨卡集合通信次数$K$，则</p>\n<div class=\"formula\">$$T_{\\text{comm}} \\approx K\\cdot\\frac{N_l\\cdot b_{\\text{act}}}{BW_{\\text{NVLink}}}\\cdot\\frac{P-1}{P}$$</div>\n<p>$b_{\\text{act}}$是传输位宽。$P$增大时$\\frac{P-1}{P}$趋近1，通信时间不再随并行度摊薄，而GEMM时间按$1/P$下降，交叉点就是规模上限。具体例子：GB200 NVL72机架内做长视频批的序列并行，跨卡激活同步在每步去噪里固定发生，当并行度超过某个值后，通信占比压过FP4带来的GEMM收益，此时更优的做法是减少跨卡层数、把并行限制在注意力之外的FFN段，让FP4 GEMM留在单卡内完成。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-35\">三十五 · 功耗与热：FP4吞吐背后的能量账</h3>\n<p>FP4张量核心吞吐约为FP8两倍，但吞吐翻倍不等于能效翻倍。E2M1的乘法器更窄，单次MAC的能量低于FP8，然而两级缩放的deq指令、scale读取、以及为保精度而保留的BF16残差与LayerNorm都在持续耗能。整步功耗可粗略分解为GEMM阵列功耗、HBM访问功耗、以及控制与反量化功耗三块；在小batch下第三块占比上升，因为阵列利用率低而指令流不减。机架级部署时，GB200/GB300 NVL72的功耗预算约束的是持续吞吐而非峰值吞吐：如果每步里有大量时间花在等scale加载与反量化，功耗花在了不产出FLOPs的指令上，每瓦有效吞吐下降。</p>\n<p>工程上的抓手是提高阵列占用率——足够大的批与足够大的GEMM让FP4 MMA连续发射，把deq开销藏在流水里；这与第二节的结论一致，但动机从时延换成能效。具体例子：同一DiT在低batch下每步时延受反量化主导，功耗却不低，因为SM在空转等数据；把批提到FP4 kernel效率达标的区间后，每步功耗上升但每帧能耗下降，容量规划应按“每帧焦耳”而非“每步功率”评估机架装机能效。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-36\">三十六 · 尾延迟：谁在长视频上先崩</h3>\n<p>平均每步时延好看不代表SLO达标，视频DiT的尾延迟由最慢的那一步决定，而最慢的步往往出现在运动剧烈片段：per-token块量化按token统计amax，跨帧动态范围大时amax跳变，量化误差上升，误差累积到VAE解码端表现为闪烁与条带。这类片段不会让单步变慢多少，但会触发更多的残差补偿与校正路径，尾部的P99被拉长。更硬的尾部来源是批内异构：一个批里混着静态长镜头与剧烈运动片段，前者早早算完，后者拖着整个批的完成时间，连续批处理若按请求而非按步调度，尾延迟会被最长请求绑架。</p>\n<p>尾延迟的显存侧诱因是激活峰值：运动剧烈片段的per-token量化需要更大的临时缓冲与校准统计，峰值显存抬高后可能触发调度器降批，降批又让FP4 kernel效率掉出稳态，形成“尾延迟—降批—效率下降—尾延迟更长”的正反馈。失败模式的另一半在注意力：若把QK^T与PV也压到FP4，logits误差敏感导致注意力图失真，稀疏与稠密区域均出现结构崩坏，这类崩坏不表现为时延，而表现为重算与校正，同样计入尾延迟。具体例子：长视频流式分块场景下，块边界处的重叠区激活动态范围最大，尾延迟常集中在这里；把重叠区的注意力与残差锁在FP8/BF16、只让FFN走FP4，是用精度分配换尾部稳定性的直接手段。</p>\n<p>规模上去以后先崩的顺序，按本算法的约束可以排出：显存先于带宽崩，因为激活与潜变量的批扩展成本由保留精度部分主导；带宽在中等batch下让位于反量化开销，表现为加速比被Amdahl限制；通信在跨卡序列并行引入后成为固定税；尾延迟最后崩，且崩在运动剧烈片段与批内异构上。容量规划的正确顺序是先定每请求激活字节与目标batch，再验证FP4 kernel在该batch下是否进入稳态，最后才看跨卡拓扑——把顺序倒过来，会在机架规模上得到一条平均吞吐漂亮、P99不可用的曲线。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-37\">三十七 · 规模放大后的瓶颈次序：反量化开销、注意力精度保留与批上限</h3>\n<p>把NVFP4推到长视频批量去噪的规模上，最先崩的通常不是FP4 GEMM本身，而是围绕它的三件事：逐token块的量化/反量化指令、必须留在FP8/BF16的注意力与残差路径、以及由激活显存决定的batch上限。权重显存降到BF16的约1/4，B200 HBM3e下每步权重读取时间近似线性下降，这确实抬高了长视频高分辨率latent的batch上限；但端到端加速比被Amdahl关系钳住：设FFN与投影GEMM占单步时延比例为$f$、该路径加速比为$S_{\\text{FP4}}$（FP4张量核心峰值吞吐约为FP8的2倍，实际受scale加载与反量化拖累低于此值），则单步时延下界为$T\\ge T_0\\left[(1-f)+f/S_{\\text{FP4}}\\right]$。注意力QK^T与PV必须留在FP8或BF16，残差与LayerNorm保持BF16，这部分不进$f$，于是$f$越小、规模越大，收益越被稀释。工程判断是：先量出$f$再决定是否值得为某层引入FP4，而不是整网一刀切。</p>\n<p>反量化与缩放因子读取的代价随batch反向变化，这是最容易被误判的失效条件。两级缩放写为</p>\n<div class=\"formula\">$$w\\approx s_{FP32}\\cdot s_{E4M3}^{(g)}\\cdot q_{E2M1},\\qquad \\hat{W}_{i}=s_{\\text{blk},i}\\cdot s_{\\text{glob}}\\cdot \\mathrm{deq}(W^{\\text{FP4}}_{i})$$</div>\n<p>每16元素一组共享一个E4M3微缩放、块间再乘一个FP32全局缩放，意味着每次MMA前都要把scale搬进寄存器并做一次乘回。低batch或小GEMM时，这些SM指令与scale访存延迟主导流水，FP4吞吐收益被抵消，端到端时延不降反升——这是典型的Amdahl反向失效：并行度不足时，串行的准备开销占比上升。批大小因此存在一个由激活显存与FP4 kernel效率共同夹出的下界，低于它就该退回FP8路径，而不是硬扛NVFP4。</p>\n<p>精度侧的边界更硬。视频时空激活动态范围大，per-token块量化按token统计amax以适应跨帧变化，但运动剧烈片段的块内误差仍会上升，误差沿去噪步累积，到VAE解码端表现为闪烁与条带；校准集偏差会进一步放大时空注意力误差。因此注意力logits不能压到FP4——一旦QK^T与PV也走E2M1，logits误差敏感导致注意力图失真，稀疏与稠密区域同时出现结构崩坏。可行的折中是：对运动剧烈片段保留注意力与残差为FP8/BF16，VAE解码前对最后一层输出做BF16反量化与bias校正，把4bit误差挡在像素域之外。代价是混合精度让权重与激活的显存收益打折，KV保持BF16或FP8也吃掉一部分省下的容量。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先崩的位置</th><th>系统代价</th><th>应对</th></tr></thead><tbody><tr><td>batch 偏小 / GEMM 偏小</td><td>两级缩放的反量化指令与 scale 加载</td><td>时延不降反升，加速比受 Amdahl 限制</td><td>退回 FP8，或合并请求抬高有效 batch</td></tr><tr><td>分辨率与帧数上升</td><td>激活显存与注意力精度保留</td><td>batch 上限受激活显存约束，注意力仍占 FP8/BF16 带宽</td><td>per-token 块量化 + 仅 FFN/投影走 FP4</td></tr><tr><td>运动剧烈片段</td><td>per-token 量化误差累积</td><td>VAE 端闪烁与条带，需重跑或降质</td><td>局部保留 FP8/BF16，VAE 前 bias 校正</td></tr></tbody></table>\n<p>通信与功耗在单卡内GEMM流水为主的拓扑下不是首要瓶颈，但规模上去后并行切分一旦跨卡，NVFP4省下的权重带宽会被集合通信的固定开销重新吃掉，此时收益判断要按“每步有效计算时间/每步通信时间”重新算，而不是沿用单卡结论。真正的规模上限由注意力精度保留与反量化开销共同决定：前者禁止把最贵的注意力也压到4bit，后者禁止在低占用下空转FP4流水。可叠加的稀疏时空注意力按内容动态分配精度与稀疏度，误差来源与本方案的静态4bit量化不同，两者叠加时需分别校准，不能共用一套amax统计。</p>\n<h3 id=\"alg-nvfp4-video-dit-sec-38\">三十八 · 精度失败的三种签名：闪烁、条带、结构崩坏</h3>\n<p>NVFP4视频DiT的精度失败不会以“整体PSNR下降”这种温和方式出现，它总是以三种可区分的视觉签名暴露自己，而三者的根因完全不同，诊断时必须分开处理。第一种是<strong>闪烁</strong>：帧间同一区域的像素值在相邻帧之间小幅但高频地跳动，VAE解码后尤其明显。根因是per-token块量化的amax在跨帧时抖动——运动剧烈片段的激活动态范围逐帧变化，token块统计出的缩放因子在帧与帧之间不连续，导致同一语义位置的量化格点漂移，误差经残差累积后进入像素域。第二种是<strong>条带</strong>：画面出现水平或垂直的带状亮度断层，根因是16元素分组的E4M3微缩放因子在块边界处不匹配，块内动态范围被压得过紧时，块间过渡区的量化台阶被放大。第三种是<strong>结构崩坏</strong>：注意力图失真，稀疏区域与稠密区域同时出现语义错乱，这是把QK^T与PV也压到FP4的直接后果——logits对4bit误差极敏感，softmax后的注意力权重分布被系统性扭曲。</p>\n<p>诊断的第一步是把这三种签名与量化配置对齐。工程上应维护一张“精度分配表”作为运行时元数据：FFN与投影走NVFP4，QK^T与PV保持FP8或BF16，LayerNorm与残差保持BF16，VAE解码前对最后一层输出做BF16反量化与bias校正。任何一次精度回退都必须能定位到表中哪一行被改动。若闪烁出现而条带不出现，问题在per-token amax统计而非分组缩放；若条带出现，检查分组边界与全局FP32二级缩放的更新时机；若结构崩坏，几乎可以断定注意力路径被误压到FP4，此时不需要做逐层比对，直接回滚注意力精度即可。</p>\n<p>量化误差的可观测上界由两级缩放公式给出：</p>\n<div class=\"formula\">$$\\hat{W}_{i}=s_{\\text{blk},i}\\cdot s_{\\text{glob}}\\cdot \\mathrm{deq}(W^{\\text{FP4}}_{i}),\\quad \\Delta_{\\text{rel}}\\approx\\frac{\\lVert W-\\hat{W}\\rVert_2}{\\lVert W\\rVert_2}\\le \\frac{\\sqrt{16}\\,2^{-3}}{2\\sqrt{3}}\\cdot\\frac{1}{s_{\\text{blk}}}$$</div>\n<p>这个上界说明相对误差与块缩放因子成反比：$s_{\\text{blk}}$越小的块，误差上界越大。诊断闪烁时，应把逐帧的$s_{\\text{blk}}$分布打出来，看运动片段是否出现缩放因子塌缩到小值的块——这些块就是闪烁的源头。代价层面，闪烁不是免费问题：它迫使你在运动片段保留更高精度路径，直接抬高该片段的显存占用与GEMM时延，端到端每步去噪时延在运动帧上出现可测的抬升。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-39\">三十九 · OOM的三条路径与显存账本</h3>\n<p>NVFP4把权重压到BF16的约1/4，但OOM依然会发生，而且路径不止一条。第一条是<strong>激活显存</strong>：长视频高分辨率latent的token块数量随分辨率与帧数增长，per-token动态量化的中间缓冲、FP8残差补偿缓冲、以及反量化回BF16的输出写回，三者叠加后的激活占用往往超过权重节省下来的空间。第二条是<strong>KV与中间激活回写</strong>：机制上KV/中间激活按需回写HBM、仅保留FP8残差用于误差补偿，但如果回写策略过于保守（保留过多中间态用于误差补偿），HBM占用会随批大小线性上升。第三条是<strong>批大小与FP4 kernel效率的耦合</strong>：批大小受激活显存与FP4 kernel效率双重约束，调大batch提升kernel效率的同时激活显存按比例增长，二者在某个点上碰撞。</p>\n<p>诊断OOM不能只看总显存，要建一本显存账本，按四类分账：权重（NVFP4块布局加两级缩放因子，缩放因子本身占少量但不可忽略的常驻空间）、激活（per-token量化缓冲加FP8残差）、KV（BF16或FP8）、以及kernel工作区（cuBLASLt/CUTLASS Blackwell FP4 kernel的临时缓冲）。账本要按去噪步滚动采样，因为激活占用在采样器的不同步之间并不恒定。一个具体例子：当批大小提升到某个档位后OOM，而单步时延并未同比下降，说明瓶颈已从GEMM吞吐转移到激活显存，此时正确的动作是回退批大小而不是继续压精度——把FFN也压到更低bit不会释放激活空间，只会引入新的精度签名。</p>\n<p>工程判断上，OOM的回滚优先级应是：先降批大小，再降分辨率或帧数，最后才动精度分配表。理由是前两者只影响吞吐与SLO，后者会改变数值路径并可能触发闪烁。显存账本的另一用途是容量规划：把每类占用写成批大小与latent长度的函数，就能在部署前算出安全批上限，而不是靠试错撞墙。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-40\">四十 · 批抖动与路由不均：两个被混淆的现象</h3>\n<p>批抖动和路由不均经常被当成同一个问题，但它们的观测特征与根因相反。批抖动表现为<strong>时延随批组成变化而波动</strong>：同一批大小下，若批内请求的latent长度、帧数、运动强度差异大，per-token amax统计的耗时与FP4 kernel的实际占用率都会波动，导致每步去噪时延不稳定。根因是连续批处理下批内异构——新请求进入、旧请求退出时，批的token块构成改变，而NVFP4的激活量化是按token块做的，块数与块内amax分布随批组成漂移。路由不均则表现为<strong>部分SM或部分GEMM持续空闲</strong>：小GEMM或低batch时，两级缩放的反量化指令与scale加载开销占主导，FP4 Tensor Core的占用率上不去，工作量在SM之间分布不均。</p>\n<p>区分二者的方法是看抖动是否与批组成相关。若固定批组成后时延稳定，则是批抖动；若固定批组成后仍有SM空闲，则是路由不均。批抖动的缓解手段是批组成规整化——按latent长度分桶、限制单批内运动强度跨度，代价是调度灵活性下降、请求等待时间上升。路由不均的缓解手段是保持足够批大小以摊薄反量化开销，这与负载配方中“低batch或小GEMM时反量化开销可能抵消收益”的约束一致；代价是批大小提升带来的激活显存压力。</p>\n<p>这里有一个Amdahl式的判断：整体加速比受注意力与残差保留FP8/BF16的限制，FFN与投影的FP4收益再大，也无法让端到端时延按FP4吞吐的倍数下降。因此当观测到批抖动或路由不均时，先确认瓶颈是否真在FP4路径上——若注意力路径已占去相当比例的每步时延，优化FFN的批组成收益有限。监控上应同时采集每步的GEMM占用率、反量化指令占比、以及批内token块数的方差，三者联立才能把抖动归因到批组成还是kernel效率。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-41\">四十一 · 尾延迟尖刺：从SLO反推监控点</h3>\n<p>尾延迟尖刺在视频DiT推理里通常不是单点故障，而是<strong>多个慢步骤的叠加</strong>。SLO以每步去噪时延与端到端帧输出为主，尾延迟的成因可以分三层：第一层是批内最慢请求主导——连续批处理下批的完成时间由批内最长序列决定，一个高分辨率长视频请求进入批后，整批的每步时延被拉长；第二层是运动剧烈片段的精度路径切换——为压制闪烁而保留FP8/BF16的注意力与残差，在该片段上抬高了每步时延；第三层是反量化开销在低占用时的放大，即路由不均的极端情形。</p>\n<p>监控点应围绕SLO反推设置，而不是围绕硬件计数器堆砌。具体做法：为每个去噪步记录三个量——批内最长序列的token块数、该步实际走的精度路径组合（FFN是否NVFP4、注意力是否FP8）、以及反量化指令占该步总指令的比例。当尾延迟尖刺出现时，这三个量能直接区分是批组成问题、精度路径问题还是kernel效率问题。伪代码思路是维护一个滑动窗口的每步时延分布，对超过阈值的步做归因标记，标记维度就是上述三个量；归因结果写入回滚决策表。</p>\n<p>代价层面，尾延迟尖刺的工程成本在于它迫使你保留精度回退通道：一旦某类请求持续触发尖刺，系统需要能对该请求单独降级精度或拆分批次，而不是全局回滚。这要求部署时把精度分配表做成可按请求覆盖的配置，而不是编译期常量。一个具体例子：高分辨率长视频请求进入批后每步时延抬升，若归因显示是批内最长序列主导，正确动作是拆分批次或为该请求单独调度，而不是把FFN精度再降一档——后者不解决批组成问题，只会新增闪烁风险。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-42\">四十二 · 回滚的分级与触发条件</h3>\n<p>回滚不是单一动作，应按影响面分级。第一级是<strong>请求级精度覆盖</strong>：对触发闪烁或结构崩坏的请求，单独把注意力路径从FP4回退到FP8/BF16，或把FFN回退到FP8，其余请求不受影响。第二级是<strong>批级调度回退</strong>：对批抖动或尾延迟尖刺，回退批组成规整化策略或拆分批次，不触碰数值路径。第三级是<strong>全局精度分配回滚</strong>：仅在精度签名跨请求普遍出现时启用，把整张精度分配表退回到上一个稳定版本。三级的触发条件必须互斥且可观测：闪烁/条带/结构崩坏触发第一级，批抖动与尾延迟尖刺触发第二级，第一级回滚后签名仍复现才升级到第三级。</p>\n<p>回滚的关键工程约束是<strong>可逆性与代价对称</strong>。NVFP4的权重是离线预打包的块布局，回滚到FP8意味着要么保留一份FP8权重副本（显存代价翻倍），要么在线反量化重打包（时延代价）。因此部署配方上应预先决定：哪些层保留双精度副本、哪些层接受在线重打包。注意力与残差本就保持FP8/BF16，回滚它们几乎无代价；FFN与投影的NVFP4回滚代价最高，应作为最后手段。这与精度分配的关键约束一致——VAE解码前的BF16反量化与bias校正本身就是一道防线，闪烁若已越过这道防线进入像素域，说明误差在DiT内部已累积到不可忽略，此时回滚FFN精度比在VAE端做补偿更有效。</p>\n<p>监控与回滚要形成闭环：每次回滚都记录触发签名、归因维度、回滚级别与回滚后的时延变化。若某类请求反复触发同一签名，说明精度分配表在该负载形态下有系统性偏差，应把该负载形态写进校准集，而不是靠运行时反复回滚。校准集偏差会放大时空注意力误差，这是本算法已知的精度约束，回滚闭环的价值在于把运行时观测反哺校准集，让离线打包的缩放因子覆盖真实负载的动态范围。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-43\">四十三 · 诊断顺序与工程判断</h3>\n<p>把上述失败模式收拢成一条诊断顺序：先看视觉签名（闪烁/条带/结构崩坏），再看显存账本（权重/激活/KV/工作区），再看批组成与kernel占用率，最后看尾延迟归因。这个顺序的理由是代价递增——视觉签名只需抽样解码即可观测，显存账本需要运行时插桩，批组成与占用率需要kernel级计数器，尾延迟归因需要滑动窗口与决策表。按代价递增的顺序排查，能在最低成本处截住大部分问题。</p>\n<p>工程判断上有一条硬约束：<strong>不要把精度回滚当作吞吐问题的解法</strong>。低batch下反量化开销使加速比受Amdahl限制，这是kernel效率问题，回滚精度只会让GEMM更慢而不解决占用率。反过来，也不要把吞吐优化当作精度问题的解法——提升批大小摊薄反量化开销的同时会放大per-token amax的跨帧抖动，闪烁风险上升。两类问题的解法方向相反，诊断时必须先分清签名属于哪一类。</p>\n<p>最后一个具体机制落在回滚通道的部署形态上：精度分配表按请求可覆盖、权重副本按层可选、批调度策略按负载形态可切换，三者共同构成回滚面。回滚面的宽度决定了对失败模式的响应速度，但也带来显存与调度复杂度的代价；在Blackwell档位上，权重显存已降至BF16的约1/4，为保留FP8副本留出了空间，这使得请求级精度覆盖在多数部署里是可行的第一道防线。诊断的终点不是找到根因，而是让回滚动作落在正确的层级上，使一次失败只影响一个请求或一个批次，而不是整张精度分配表。</p>\n<h3 id=\"alg-nvfp4-video-dit-sec-44\">四十四 · 对照维度：省显存、省算力还是省带宽</h3>\n<p>把NVFP4视频DiT放回同族算法谱系里，第一个要问的不是“哪个更先进”，而是“当前瓶颈在哪一层”。NVFP4的收益结构非常明确：权重与激活压到4bit，权重显存降到BF16的约1/4，B200 HBM3e下每步权重读取时间近似线性下降，同时GEMM落到原生FP4张量核心，峰值吞吐约为FP8的2倍。它解决的是<strong>显存容量 + 权重带宽 + FFN/投影GEMM吞吐</strong>三件事，但对注意力本身的算力与带宽几乎不动——因为QK^T与PV必须留在FP8或BF16。</p>\n<p>相邻的精度分配稀疏时空注意力走的是另一条路：按内容动态分配精度与稀疏度，直接削减注意力的算力和带宽。两者的误差来源也不同——前者是量化舍入误差经两级缩放与残差补偿后被压住，后者是稀疏跳过带来的结构近似误差。因此判断顺序应当是：若profile显示FFN与投影GEMM占主导、且显存装不下目标batch的长latent，NVFP4是主选；若注意力在每步时延中占比过半，先上精度分配稀疏注意力，NVFP4作为叠加项而非替代项。二者可叠加，但叠加时误差预算要分开核算，不能把量化误差与稀疏误差混在一个阈值里调。</p>\n<div class=\"formula\">$$\\Delta_{\\text{rel}}\\approx\\frac{\\lVert W-\\hat{W}\\rVert_2}{\\lVert W\\rVert_2}\\le \\frac{\\sqrt{16}\\,2^{-3}}{2\\sqrt{3}}\\cdot\\frac{1}{s_{\\text{blk}}}$$</div>\n<p>这条界说明块级缩放因子越小、相对误差上界越大，所以per-token块的amax统计质量直接决定误差天花板。对照轨迹感知缓存复用：后者省的是“重复去噪步的算力”，与NVFP4省的是“单步内的权重带宽与GEMM吞吐”，二者正交，缓存复用不改变量化误差，量化也不改变缓存命中逻辑，可以同时开，但缓存复用会拉长单次前向的序列长度，反过来加重激活显存的压力，需要重新核算batch上限。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-45\">四十五 · 决策表：按瓶颈与SLO选主算法</h3>\n<p>下表把同族条目按“主省什么、代价落在哪、适用条件”三列对齐，供工程选型时直接查表。表中不重复各条目自身的机制细节，只保留选型判据。</p>\n<table class=\"mini\"><thead><tr><th>算法</th><th>主省</th><th>主要代价</th><th>适用条件</th></tr></thead><tbody>\n<tr><td>NVFP4分块量化推理（本条）</td><td>权重显存、权重带宽、FFN/投影GEMM吞吐</td><td>反量化指令与scale加载；激活离群值敏感</td><td>Blackwell档位、计算受限的FFN与投影、batch足够大</td></tr>\n<tr><td>精度分配稀疏时空注意力</td><td>注意力算力与带宽</td><td>稀疏结构近似误差；动态判定开销</td><td>注意力占每步时延主导、内容稀疏性可利用</td></tr>\n<tr><td>FP8时空注意力内核</td><td>注意力GEMM吞吐与激活带宽</td><td>仍需FP8精度保留，省显存有限</td><td>注意力是瓶颈但稀疏性不足、要求精度保守</td></tr>\n<tr><td>轨迹感知缓存复用与校正</td><td>跨步重复计算</td><td>缓存显存占用；校正逻辑引入额外前向</td><td>相邻去噪步潜变量变化小、步数多</td></tr>\n<tr><td>少步蒸馏采样</td><td>总步数</td><td>蒸馏后质量上限；教师模型依赖</td><td>端到端帧输出SLO紧、可接受质量折衷</td></tr>\n<tr><td>自回归视频2bit KV量化</td><td>KV显存与读取带宽</td><td>KV精度损失在长上下文累积</td><td>自回归形态、KV为显存主占用</td></tr>\n<tr><td>视频自回归投机解码</td><td>解码步数</td><td>草稿模型显存与验证开销</td><td>自回归形态、接受率可维持</td></tr>\n<tr><td>预填解码分离服务</td><td>阶段间干扰、TTFT与TPOT解耦</td><td>跨节点KV传输带宽</td><td>长短请求混合、SLO分阶段考核</td></tr>\n<tr><td>长视频流式分块重叠</td><td>峰值显存、首帧时延</td><td>重叠区重复计算</td><td>超长视频、显存装不下整段latent</td></tr>\n<tr><td>VAE分块重叠解码</td><td>VAE解码峰值显存</td><td>重叠区重复解码</td><td>高分辨率输出、解码阶段显存受限</td></tr>\n</tbody></table>\n<p>读表方法是先定位瓶颈列：若“权重带宽/显存”是主矛盾，选NVFP4；若“注意力算力”是主矛盾，选精度分配稀疏注意力或FP8注意力内核；若“步数或重复计算”是主矛盾，选缓存复用或少步蒸馏。注意NVFP4与少步蒸馏的交互：步数减少后，每步的反量化固定开销在总时延中占比上升，低batch下Amdahl限制更明显，此时要么提高batch摊薄，要么退回FP8路径。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-46\">四十六 · 适用条件的量化判据</h3>\n<p>选型不能停在定性。对NVFP4，可用一条粗略的收益判据：设单步中FFN与投影GEMM占比为$f$，FP4相对FP8的吞吐提升为$k$（Blackwell上约为2），反量化与scale加载带来的额外开销占比为$c$，则端到端加速比上界近似为</p>\n<div class=\"formula\">$$S\\approx\\frac{1}{(1-f)+f/k+c}$$</div>\n<p>当$f$接近1且$c$可忽略时$S$趋近$k$；当$f$只有一半、注意力仍走FP8/BF16时，$S$被Amdahl项$(1-f)$压住，这就是“整体加速比受注意力与残差保留FP8/BF16限制”的定量表达。$c$在低batch或小GEMM时不可忽略——两级缩放的反量化指令与scale加载开销可能超过FP4吞吐收益，端到端时延不降反升。因此适用条件应写成：$f$足够高、batch足够大使GEMM规模撑起FP4效率、$c$被摊薄。</p>\n<p>对精度分配稀疏注意力，判据换成“可跳过比例$\\rho$与判定开销$d$”：加速比近似$1/((1-\\rho)+\\rho/k_s+d)$，其中$k_s$为稀疏执行相对稠密的效率增益。若内容稀疏性低（$\\rho$小），该算法收益迅速衰减，此时NVFP4反而是更稳的选择，因为它不依赖内容分布。具体例子：一段运动剧烈的长视频，跨帧动态范围大，per-token块量化误差上升，同时时空稀疏性也下降——两个算法的收益同时被削弱，正确做法是保留注意力与残差为FP8/BF16、仅FFN与投影走FP4，并在VAE解码前做BF16反量化与bias校正，而不是把注意力也压到FP4。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-47\">四十七 · 组合顺序与误差预算分配</h3>\n<p>多算法叠加时的顺序影响误差累积路径。推荐顺序是：先做结构性削减（长视频流式分块重叠、VAE分块重叠解码）确定显存骨架，再做精度削减（NVFP4权重与激活、注意力FP8/BF16保留），最后做计算削减（缓存复用、少步蒸馏、稀疏注意力）。理由是先削减精度再削减结构，会让量化误差在更长的序列上累积，误差进入VAE解码端表现为闪烁与条带的概率上升；而先定结构，量化误差的作用域被限制在确定的块内。</p>\n<p>误差预算要按域分开：像素域误差主要由VAE前的最后一层输出决定，因此那里必须BF16反量化加bias校正；注意力域误差由logits精度决定，QK^T与PV留在FP8或BF16；权重域误差由两级缩放与残差补偿控制，仅保留FP8残差用于误差补偿。三者不能共用同一个容差阈值。一个具体判断：若诊断显示闪烁出现在运动剧烈片段而非静止片段，问题在per-token量化的amax统计跨帧不稳，应先调token块统计窗口，而不是去动稀疏注意力的阈值；反之若结构崩坏在稀疏与稠密区域同时出现，则是注意力被压到FP4导致logits失真，应回退注意力精度。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-48\">四十八 · 部署拓扑与算法选择的耦合</h3>\n<p>算法选择还受部署形态约束。NVFP4面向Blackwell档位，依赖原生FP4张量核心与HBM3e带宽，并行拓扑以单卡内GEMM流水为主，这意味着它天然适配单卡或少卡紧耦合的批量去噪服务；若服务采用预填解码分离，NVFP4的权重压缩会同时降低跨节点权重加载与KV传输的压力，但分离架构下解码节点的batch往往偏小，反量化开销$c$占比上升，需要在分离点做batch聚合。</p>\n<p>对照自回归视频2bit KV量化：那条路线的主战场是KV显存，与NVFP4的权重显存不冲突，二者可同时启用，但KV压到2bit后注意力读取带宽下降，可能使$f$（FFN与投影占比）相对上升，反而提升NVFP4的加速比上界——这是一个正向耦合。对照投机解码：草稿模型若也用NVFP4，草稿的显存与带宽同步下降，验证阶段的主模型仍按混合精度执行，接受率不受量化影响，但草稿与主模型的量化方案不一致会引入分布偏差，需保持同一两级缩放配置。</p>\n<p>容量规划上，NVFP4把权重显存降到BF16的约1/4，直接抬高长视频高分辨率latent的batch上限，但batch上限最终由激活显存与FP4 kernel效率共同约束，而不是权重。因此容量估算应先算激活峰值，再算权重，最后用$S$判据校验batch是否足以摊薄$c$。若算出的batch落在小GEMM区间，说明该负载不适合纯NVFP4，应改为FFN/投影NVFP4、注意力FP8的混合配置，或引入缓存复用拉长有效计算量。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-49\">四十九 · 选型的工程落点</h3>\n<p>最终判断落在一条可执行的检查链上：第一步profile确认FFN与投影GEMM占比$f$与注意力占比；第二步确认batch是否足以让FP4 kernel进入高效区间，否则$c$会吃掉收益；第三步确认注意力精度是否必须保留FP8/BF16，若必须，则接受Amdahl上限并把优化重心转向注意力侧算法；第四步确认VAE前的反量化与bias校正路径已就位，否则4bit误差进入像素域。四步中任一步不满足，NVFP4就不是主选，而应作为叠加项与精度分配稀疏注意力或FP8注意力内核组合。</p>\n<p>同族算法之间不存在普适最优，只存在瓶颈匹配。NVFP4的独特价值在于它是静态的、与内容分布无关的削减，因此在内容动态范围大、稀疏性不稳定的视频负载上比动态精度分配更可预测；代价是它把优化上限锁在Amdahl项上，注意力侧的任何节省都必须由别的条目承担。工程上把这条边界写进容量模型，比追求单点加速比更重要。</p>\n\n<h3 id=\"alg-nvfp4-video-dit-sec-50\">五十 · 与稀疏时空注意力及 FP8 路线的取舍边界</h3>\n<p>本方案与“按内容动态分配精度与稀疏度”的稀疏时空注意力不是替代关系，而是正交叠加：前者静态压缩权重与激活的位宽以换取 GEMM 吞吐与权重带宽，后者动态裁剪注意力计算量以省算力。两者误差来源不同——NVFP4 的误差来自 E2M1 对离群值的截断与两级缩放的块内残差，稀疏注意力的误差来自被跳过的 token 对。若同时启用，必须保证注意力分支仍走 FP8/BF16，否则 logits 失真会与稀疏掩码叠加，在稠密区与稀疏区同时出现结构崩坏。判断是否叠加的准则是：当每步时延中 FFN 与投影 GEMM 占比高于注意力占比时，先上 NVFP4；当注意力本身已成瓶颈且运动幅度可控时，先上稀疏。二者同时上只在批大小足够、FP4 kernel 占用率饱和时才有净收益。</p>\n<p>相对纯 FP8 路线，NVFP4 的收益边界可由权重读取时间估算：权重显存降至 BF16 的约 1/4、FP8 的约 1/2，B200 HBM3e 下每步权重读取时间近似线性下降，长视频高分辨率 latent 的 batch 上限随之提升；FP4 张量核心峰值吞吐约为 FP8 的 2 倍。但端到端加速比受 Amdahl 限制——注意力 QK^T 与 PV 保留 FP8/BF16、LayerNorm 与残差保留 BF16，这部分不随量化变快。块内相对误差的量级可写成</p>\n<div class=\"formula\">$$\\Delta_{\\text{rel}}\\approx\\frac{\\lVert W-\\hat{W}\\rVert_2}{\\lVert W\\rVert_2}\\le \\frac{\\sqrt{16}\\,2^{-3}}{2\\sqrt{3}}\\cdot\\frac{1}{s_{\\text{blk}}}$$</div>\n<p>它说明误差随块缩放因子 $s_{\\text{blk}}$ 反比放大：per-token 块统计 amax 时，跨帧动态范围大的 token 会把 $s_{\\text{blk}}$ 抬高，反而放大该块的相对误差，这正是运动剧烈片段闪烁与条带的来源。因此校准集必须覆盖快速运动与场景切换，否则偏差直接进入时空注意力。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>选 NVFP4</th><th>选 FP8</th><th>选稀疏注意力</th></tr></thead><tbody><tr><td>计算受限的 FFN/投影 GEMM</td><td>是</td><td>备选</td><td>否</td></tr><tr><td>注意力 logits 精度敏感</td><td>否（仅 FFN）</td><td>是</td><td>可叠加</td></tr><tr><td>低 batch / 小 GEMM</td><td>否</td><td>是</td><td>否</td></tr><tr><td>长视频显存与带宽受限</td><td>是</td><td>备选</td><td>否</td></tr><tr><td>运动剧烈片段占比高</td><td>需保留 FP8 分支</td><td>是</td><td>谨慎</td></tr></tbody></table>\n<p>失效条件集中在两处：低 batch 或小 GEMM 时，两级缩放的反量化指令与 scale 加载开销超过 FP4 吞吐收益，端到端时延不降反升，此时应回退 FP8 并保持足够批大小以摊薄固定开销；把注意力 QK^T 与 PV 也压到 FP4 时，logits 误差敏感导致注意力图失真。工程判断是：NVFP4 的适用边界为 Blackwell 档位、计算受限的 FFN 与投影 GEMM，规模上限由注意力精度保留与反量化开销共同约束；VAE 解码前必须做 BF16 反量化与 bias 校正，把 4bit 误差挡在像素域之外。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2025 · 少步蒸馏与轨迹缓存复用</td></tr><tr><td>解决什么</td><td>视频DiT在Blackwell上以BF16推理时权重与激活占用大量显存与带宽，单卡难以承载长视频潜变量序列，且逐层反量…</td></tr><tr><td>一句话机制</td><td>用NVFP4（E2M1加两级缩放）对DiT线性层权重与激活做块级微缩放量化，配合Blackwell原生FP4张量核心与…</td></tr><tr><td>代价与失效</td><td>激活离群值对E2M1极敏感，需逐token块校准，校准集偏差会放大时空注意力误差；反量化与缩放因子读取引入额外SM指令，低占用小batch…</td></tr><tr><td>后继</td><td>深度压缩VAE与低bit latent解码</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-nvfp4-video-dit · 共 8 个片段</p>\n";break;}}})();
